  readonly id: string;
  name: string;
  email: string;
  avatarUrl?: string;
};
```

#### With stricter email and URL branding

```typescript
type Brand<T, B extends string> = T & { readonly _brand: B };

type Email    = Brand<string, "Email">;
type Url      = Brand<string, "Url">;
type UserId   = Brand<string, "UserId">;

interface User {
  readonly id: UserId;
  name:        string;
  email:       Email;
  avatarUrl?:  Url;
}
