## TypeScript User Type Declaration

### Basic Interface Declaration

```typescript
interface User {
  id: string | number;
  name: string;
  email: string;
  avatarUrl?: string;
}
```

---

### Comprehensive Declaration with Variants

```typescript
// ─── Branded Types for Type Safety ───────────────────────────────────────────

type UserId = string & { readonly _brand: "UserId" };

// ─── Core User Shape ──────────────────────────────────────────────────────────

interface User {
  readonly id: UserId;
  name: string;
  email: string;
  avatarUrl?: string | null;
}

// ─── Utility Variants ─────────────────────────────────────────────────────────

/** User shape returned from the API (all fields guaranteed) */
type UserWithAvatar = Required<User>;

/** Safe subset for public-facing contexts */
type PublicUser = Pick<User, "id" | "name" | "avatarUrl">;

/** Payload for creating a new user (no id yet) */
type CreateUserPayload = Omit<User, "id">;

/** Payload for partial updates */
type UpdateUserPayload = Partial<Omit<User, "id">>;

// ─── Type Guard ───────────────────────────────────────────────────────────────

function isUser(value: unknown): value is User {
  return (
    typeof value === "object" &&
    value !== null &&
    "id" in value &&
    "name" in value &&
    "email" in value &&
    typeof (value as User).name === "string" &&
    typeof (value as User).email === "string"
  );
}

// ─── Factory Helper ───────────────────────────────────────────────────────────

function createUser(
  id: string,
  name: string,
  email: string,
  avatarUrl?: string
): User {
  return {
    id: id as UserId,
    name,
    email,
    ...(avatarUrl !== undefined && { avatarUrl }),
  };
}
```

---

### Usage Examples

```typescript
// Valid user objects
const user: User = {
  id: "usr_01" as UserId,
  name: "Alice Johnson",
  email: "alice@example.com",
};

const userWithAvatar: User = {
  id: "usr_02" as UserId,
  name: "Bob Smith",
  email: "bob@example.com",
  avatarUrl: "https://example.com/avatars/bob.png",
};

// Using utility types
const payload: CreateUserPayload = {
  name: "Carol White",
  email: "carol@example.com",
};

const patch: UpdateUserPayload = {
  avatarUrl: "https://example.com/avatars/carol.png",
};

// Using the factory
const newUser = createUser("usr_03", "Dave Brown", "dave@example.com");

// Using the type guard
function processUser(data: unknown): void {
  if (isUser(data)) {
    console.log(data.name); // TypeScript knows this is a User
  }
}
```

---

### Key Design Decisions

| Decision | Reason |
|---|---|
| `readonly id` | IDs should never change after creation |
| `avatarUrl?: string \| null` | Distinguishes "not set" (`undefined`) from "explicitly removed" (`null`) |
| Branded `UserId` | Prevents accidentally passing a plain `string` where a `UserId` is expected |
| Utility type variants | Avoids duplicating fields across similar shapes |
| Type guard function | Enables safe narrowing when handling `unknown` API responses |

