  const candidate = value as Record<string, unknown>;

  return (
    (typeof candidate.id === "string" || typeof candidate.id === "number") &&
    typeof candidate.name === "string" &&
    typeof candidate.email === "string" &&
    (candidate.avatarUrl === undefined ||
