|---|---|
| `id: string` | Flexible for UUIDs, slugs, or prefixed IDs (e.g. `usr_001`) |
| `avatarUrl?: string` | `?` marks it optional; avoids forcing `null` handling |
| `interface` vs `type` | Prefer `interface` for object shapes — it's extendable and gives clearer error messages |

> **When to use `type` instead:** If you need unions, intersections, or mapped types, reach for `type`. For a plain object shape like `User`, `interface` is the idiomatic choice.

## Event Type Declaration & Parser

```typescript
// ─── Domain Types ────────────────────────────────────────────────────────────

/** Supported event names – extend this union as your system grows. */
export type EventName =
  | "user.created"
  | "user.updated"
  | "user.deleted"
  | "order.placed"
  | "order.shipped"
  | "order.cancelled"
  | "payment.succeeded"
  | "payment.failed";

/** Strongly-typed payload shapes keyed by event name. */
export interface EventPayloadMap {
  "user.created": { userId: string; email: string; role: string };
  "user.updated": { userId: string; changes: Record<string, unknown> };
  "user.deleted": { userId: string };
  "order.placed": { orderId: string; userId: string; totalCents: number };
  "order.shipped": { orderId: string; trackingNumber: string };
  "order.cancelled": { orderId: string; reason: string };
  "payment.succeeded": { paymentId: string; amountCents: number; currency: string };
  "payment.failed": { paymentId: string; errorCode: string; errorMessage: string };
}

/** A fully-typed Event discriminated by its name. */
export type Event<N extends EventName = EventName> = {
  [K in N]: {
    /** Unique event identifier. */
    id: string;
    /** Discriminant – the event name. */
    name: K;
    /** ISO-8601 timestamp string, coerced to a Date. */
    timestamp: Date;
    /** Strongly-typed payload for this event name. */
    payload: EventPayloadMap[K];
  };
}[N];

// ─── Parse Errors ────────────────────────────────────────────────────────────

export class EventParseError extends Error {
  constructor(
    message: string,
    public readonly field: string,
    public readonly received: unknown,
  ) {
    super(`[EventParseError] ${field}: ${message} (received: ${JSON.stringify(received)})`);
    this.name = "EventParseError";
  }
}

// ─── Internal Helpers ────────────────────────────────────────────────────────

const KNOWN_EVENT_NAMES = new Set<EventName>([
  "user.created",
  "user.updated",
  "user.deleted",
  "order.placed",
  "order.shipped",
  "order.cancelled",
  "payment.succeeded",
  "payment.failed",
]);

function isEventName(value: unknown): value is EventName {
  return typeof value === "string" && KNOWN_EVENT_NAMES.has(value as EventName);
}

function assertString(value: unknown, field: string): string {
  if (typeof value !== "string" || value.trim() === "") {
    throw new EventParseError("must be a non-empty string", field, value);
  }
  return value;
}

function assertNumber(value: unknown, field: string): number {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    throw new EventParseError("must be a finite number", field, value);
  }
  return value;
}

function assertRecord(value: unknown, field: string): Record<string, unknown> {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    throw new EventParseError("must be a plain object", field, value);
  }
  return value as Record<string, unknown>;
}

/** Parse each payload shape according to the event name. */
function parsePayload<N extends EventName>(
  name: N,
  raw: unknown,
): EventPayloadMap[N] {
  const obj = assertRecord(raw, "payload");

  // Use a type-assertion helper so each branch returns the correct shape.
  const cast = <T>(v: T): EventPayloadMap[N] => v as unknown as EventPayloadMap[N];

  switch (name) {
    case "user.created":
      return cast({
        userId: assertString(obj.userId, "payload.userId"),
        email:  assertString(obj.email,  "payload.email"),
        role:   assertString(obj.role,   "payload.role"),
      });

    case "user.updated":
      return cast({
        userId:  assertString(obj.userId, "payload.userId"),
        changes: assertRecord(obj.changes, "payload.changes"),
      });

    case "user.deleted":
      return cast({
        userId: assertString(obj.userId, "payload.userId"),
      });

    case "order.placed":
      return cast({
        orderId:    assertString(obj.orderId,    "payload.orderId"),
        userId:     assertString(obj.userId,     "payload.userId"),
        totalCents: assertNumber(obj.totalCents, "payload.totalCents"),
      });

    case "order.shipped":
      return cast({
        orderId:        assertString(obj.orderId,        "payload.orderId"),
        trackingNumber: assertString(obj.trackingNumber, "payload.trackingNumber"),
      });

    case "order.cancelled":
      return cast({
        orderId: assertString(obj.orderId, "payload.orderId"),
        reason:  assertString(obj.reason,  "payload.reason"),
      });

    case "payment.succeeded":
      return cast({
        paymentId:   assertString(obj.paymentId,   "payload.paymentId"),
        amountCents: assertNumber(obj.amountCents,  "payload.amountCents"),
        currency:    assertString(obj.currency,     "payload.currency"),
      });

    case "payment.failed":
      return cast({
        paymentId:    assertString(obj.paymentId,    "payload.paymentId"),
        errorCode:    assertString(obj.errorCode,    "payload.errorCode"),
        errorMessage: assertString(obj.errorMessage, "payload.errorMessage"),
      });

    default: {
      // Exhaustiveness check – TypeScript will error if a case is missing.
      const _exhaustive: never = name;
      throw new EventParseError("unhandled event name", "name", _exhaustive);
    }
  }
}

// ─── Public API ──────────────────────────────────────────────────────────────

/**
 * Parse an unknown value into a strongly-typed `Event`.
 *
 * @throws {EventParseError} when any required field is missing or has the wrong type.
 *
 * @example
 * const event = parseEvent(JSON.parse(rawJson));
 * if (event.name === "user.created") {
 *   console.log(event.payload.email); // ✅ fully typed
 * }
 */
export function parseEvent(raw: unknown): Event {
  const obj = assertRecord(raw, "(root)");

  // ── id ──────────────────────────────────────────────────────────────────
  const id = assertString(obj.id, "id");

  // ── name ────────────────────────────────────────────────────────────────
  if (!isEventName(obj.name)) {
    throw new EventParseError(
      `must be one of: ${[...KNOWN_EVENT_NAMES].join(", ")}`,
      "name",
      obj.name,
    );
  }
  const name = obj.name; // narrowed to EventName

  // ── timestamp ───────────────────────────────────────────────────────────
  const rawTs = obj.timestamp;
  let timestamp: Date;

  if (rawTs instanceof Date) {
    timestamp = rawTs;
  } else if (typeof rawTs === "string" || typeof rawTs === "number") {
    timestamp = new Date(rawTs);
  } else {
    throw new EventParseError(
      "must be a Date, ISO-8601 string, or Unix ms number",
      "timestamp",
      rawTs,
    );
  }

  if (isNaN(timestamp.getTime())) {
    throw new EventParseError("resolved to an invalid Date", "timestamp", rawTs);
  }

  // ── payload ─────────────────────────────────────────────────────────────
  const payload = parsePayload(name, obj.payload);

  return { id, name, timestamp, payload } as Event;
}
```

