## Usage Examples

```typescript
// ─── Happy path ──────────────────────────────────────────────────────────────
const event = parseEvent({
  id: "evt_001",
  name: "user.created",
  timestamp: "2024-06-01T12:00:00Z",
  payload: { userId: "u_42", email: "alice@example.com", role: "admin" },
});

// TypeScript narrows the payload automatically via the discriminant:
if (event.name === "user.created") {
  console.log(event.payload.email);  // ✅ string
  console.log(event.timestamp);      // ✅ Date object
}

// ─── Error path ──────────────────────────────────────────────────────────────
try {
  parseEvent({ id: "", name: "order.placed", timestamp: "bad-date", payload: {} });
} catch (err) {
  if (err instanceof EventParseError) {
    console.error(err.message); // [EventParseError] id: must be a non-empty string …
    console.error(err.field);   // "id"
  }
}
```

