## Key Design Decisions

| Decision | Rationale |
|---|---|
| **Discriminated union via mapped type** | `Event<N>` distributes over `EventName` so narrowing on `.name` automatically types `.payload` |
| **`EventPayloadMap` interface** | Single source of truth; adding a new event only requires one entry here + one `switch` case |
| **`EventParseError` with `field`** | Structured errors make logging and debugging straightforward |
| **Exhaustiveness check (`never`)** | TypeScript will fail to compile if a new `EventName` is added without a matching `switch` case |
| **Flexible timestamp input** | Accepts `Date`, ISO string, or Unix-ms number – common in real-world APIs |

## Event Type Declaration & Parser

```typescript
// ─── Types ────────────────────────────────────────────────────────────────────

/** Allowed primitive payload values */
type PayloadValue =
  | string
  | number
  | boolean
  | null
  | PayloadValue[]
  | { [key: string]: PayloadValue };

/** Typed payload – a record of arbitrary depth */
type Payload = Record<string, PayloadValue>;

/** The canonical Event shape returned by parseEvent */
interface Event {
  /** Human-readable event name (e.g. "user.created") */
  name: string;
  /** Normalised UTC timestamp */
  timestamp: Date;
  /** Arbitrary structured data attached to the event */
  payload: Payload;
}

// ─── Custom Error ─────────────────────────────────────────────────────────────

class EventParseError extends Error {
  constructor(
    message: string,
    public readonly field: string,
    public readonly received: unknown
  ) {
    super(`[EventParseError] ${field}: ${message} (received: ${JSON.stringify(received)})`);
    this.name = "EventParseError";
  }
}

// ─── Guards & Helpers ─────────────────────────────────────────────────────────

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function parseName(raw: unknown): string {
  if (typeof raw !== "string") {
    throw new EventParseError("must be a string", "name", raw);
  }

  const trimmed = raw.trim();

  if (trimmed.length === 0) {
    throw new EventParseError("must not be empty", "name", raw);
  }

  // Optional: enforce a naming convention like "category.action"
  if (!/^[a-zA-Z0-9_.-]+$/.test(trimmed)) {
    throw new EventParseError(
      "must contain only alphanumeric characters, dots, hyphens, or underscores",
      "name",
      raw
    );
  }

  return trimmed;
}

function parseTimestamp(raw: unknown): Date {
  let date: Date;

  if (raw instanceof Date) {
    date = raw;
  } else if (typeof raw === "string" || typeof raw === "number") {
    date = new Date(raw);
  } else {
    throw new EventParseError(
      "must be a Date, ISO string, or Unix timestamp (ms)",
      "timestamp",
      raw
    );
  }

  if (isNaN(date.getTime())) {
    throw new EventParseError("resolved to an invalid date", "timestamp", raw);
  }

  return date;
}

function parsePayloadValue(value: unknown, path: string): PayloadValue {
  if (value === null) return null;

  switch (typeof value) {
    case "string":
    case "number":
    case "boolean":
      return value;

    case "object":
      if (Array.isArray(value)) {
        return value.map((item, i) => parsePayloadValue(item, `${path}[${i}]`));
      }

      if (isPlainObject(value)) {
        return parsePayload(value, path);
      }

      throw new EventParseError(
        "unsupported object type in payload",
        path,
        value
      );

    default:
      throw new EventParseError(
        `unsupported type "${typeof value}" in payload`,
        path,
        value
      );
  }
}

function parsePayload(raw: unknown, path = "payload"): Payload {
  if (!isPlainObject(raw)) {
    throw new EventParseError("must be a plain object", path, raw);
  }

  const result: Payload = {};

  for (const [key, value] of Object.entries(raw)) {
    result[key] = parsePayloadValue(value, `${path}.${key}`);
  }

  return result;
}

// ─── Main Parser ──────────────────────────────────────────────────────────────

/**
 * Parses an unknown value into a strongly-typed `Event`.
 *
 * @param raw - Any value (API response, message queue payload, etc.)
 * @returns A validated `Event` object
 * @throws `EventParseError` if any field is missing or invalid
 *
 * @example
 * const event = parseEvent({
 *   name: "user.created",
 *   timestamp: "2024-06-01T12:00:00Z",
 *   payload: { userId: 42, email: "alice@example.com" },
 * });
 */
function parseEvent(raw: unknown): Event {
  if (!isPlainObject(raw)) {
    throw new EventParseError(
      "event must be a plain object",
      "<root>",
      raw
    );
  }

  return {
    name:      parseName(raw["name"]),
    timestamp: parseTimestamp(raw["timestamp"]),
    payload:   parsePayload(raw["payload"]),
  };
}

// ─── Usage Examples ───────────────────────────────────────────────────────────

// ✅ Valid event
const event = parseEvent({
  name: "order.placed",
  timestamp: "2024-06-01T12:00:00Z",
  payload: {
    orderId: "abc-123",
    total: 99.99,
    items: [{ sku: "WIDGET", qty: 2 }],
    express: true,
    coupon: null,
  },
});

console.log(event);
/*
{
  name: 'order.placed',
  timestamp: 2024-06-01T12:00:00.000Z,   ← real Date object
  payload: {
    orderId: 'abc-123',
    total: 99.99,
    items: [ { sku: 'WIDGET', qty: 2 } ],
    express: true,
    coupon: null
  }
}
*/

// ❌ Invalid – missing name
try {
  parseEvent({ timestamp: Date.now(), payload: {} });
} catch (e) {
  console.error((e as EventParseError).message);
  // [EventParseError] name: must be a string (received: undefined)
}

// ❌ Invalid – bad timestamp
try {
  parseEvent({ name: "ping", timestamp: "not-a-date", payload: {} });
} catch (e) {
  console.error((e as EventParseError).message);
  // [EventParseError] timestamp: resolved to an invalid date (received: "not-a-date")
}

// ❌ Invalid – function in payload
try {
  parseEvent({ name: "ping", timestamp: Date.now(), payload: { fn: () => {} } });
} catch (e) {
  console.error((e as EventParseError).message);
  // [EventParseError] payload.fn: unsupported type "function" in payload ...
}
```

