## Key Design Decisions

| Concern | Choice | Rationale |
|---|---|---|
| **Payload type** | Recursive `PayloadValue` | Handles arbitrary nesting without `any` |
| **Timestamp input** | `string \| number \| Date` | Accepts ISO strings, Unix ms, and `Date` objects |
| **Error type** | Custom `EventParseError` | Carries `field` + `received` for structured logging |
| **Payload path tracking** | Dot-notation string (`payload.items[0].sku`) | Pinpoints exactly where deep validation fails |
| **No external deps** | Pure TypeScript | Zero runtime overhead; swap in Zod/Valibot if preferred |

## Event Type Declaration & Parser

### Types

```typescript
// Event payload can be any JSON-serializable value
type JsonPrimitive = string | number | boolean | null;
type JsonValue =
  | JsonPrimitive
  | JsonValue[]
  | { [key: string]: JsonValue };

type EventPayload = Record<string, JsonValue>;

interface Event {
  name: string;
  timestamp: Date;
  payload: EventPayload;
}
```

### Validation Helpers

```typescript
class ParseError extends Error {
  constructor(
    message: string,
    public readonly field: string,
    public readonly received: unknown
  ) {
    super(`[ParseError] ${field}: ${message}. Received: ${JSON.stringify(received)}`);
    this.name = "ParseError";
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isJsonValue(value: unknown): value is JsonValue {
  if (value === null) return true;

  switch (typeof value) {
    case "string":
    case "number":
    case "boolean":
      return true;
    case "object":
      if (Array.isArray(value)) {
        return value.every(isJsonValue);
      }
      return isRecord(value) && Object.values(value).every(isJsonValue);
    default:
      return false;
  }
}

function isEventPayload(value: unknown): value is EventPayload {
  return isRecord(value) && Object.values(value).every(isJsonValue);
}

function parseTimestamp(value: unknown, field: string): Date {
  if (value instanceof Date) {
    if (isNaN(value.getTime())) {
      throw new ParseError("invalid Date object", field, value);
    }
    return value;
  }

  if (typeof value === "string" || typeof value === "number") {
    const date = new Date(value);
    if (isNaN(date.getTime())) {
      throw new ParseError("cannot be parsed as a valid date", field, value);
    }
    return date;
  }

  throw new ParseError(
    "must be a Date, ISO string, or Unix timestamp (number)",
    field,
    value
  );
}
```

### Main Parser

```typescript
function parseEvent(raw: unknown): Event {
  // 1. Must be a plain object
  if (!isRecord(raw)) {
    throw new ParseError("event must be a non-null object", "root", raw);
  }

  // 2. Validate `name`
  const { name, timestamp, payload } = raw;

  if (typeof name !== "string") {
    throw new ParseError("must be a string", "name", name);
  }
  if (name.trim().length === 0) {
    throw new ParseError("must not be empty", "name", name);
  }

  // 3. Validate `timestamp`
  const parsedTimestamp = parseTimestamp(timestamp, "timestamp");

  // 4. Validate `payload`
  if (!isEventPayload(payload)) {
    throw new ParseError(
      "must be a record with JSON-serializable values",
      "payload",
      payload
    );
  }

  return {
    name: name.trim(),
    timestamp: parsedTimestamp,
    payload,
  };
}
```

### Usage Examples

```typescript
