  name: "user.signup",
  timestamp: "2024-06-01T12:00:00.000Z",
  payload: { userId: "abc123", plan: "pro", trialDays: 14 },
});
console.log(e1);
// { name: 'user.signup', timestamp: Date(...), payload: { userId: 'abc123', ... } }

// ✅ Valid — Unix timestamp (ms)
