// ❌ Bad timestamp → ParseError: [ParseError] timestamp: cannot be parsed as a valid date
parseEvent({ name: "test", timestamp: "not-a-date", payload: {} });

// ❌ Non-serializable payload → ParseError: [ParseError] payload: must be a record...
parseEvent({ name: "test", timestamp: new Date(), payload: { fn: () => {} } });
