  }),

  "payment.failed": (raw) => ({
    paymentId: assertString(raw.paymentId, "payload.paymentId"),
    errorCode: assertString(raw.errorCode, "payload.errorCode"),
    message: assertString(raw.message, "payload.message"),
  }),
};

// ─── Main Parser ──────────────────────────────────────────────────────────────

/**
 * Parses an unknown value into a strongly-typed `Event`.
 *
 * @throws {EventParseError} when any required field is missing or invalid.
 *
 * @example
 * const event = parseEvent({
 *   id: "evt_01",
 *   name: "user.created",
 *   timestamp: "2024-06-01T12:00:00.000Z",
 *   payload: { userId: "u_1", email: "alice@example.com", role: "admin" },
 * });
 * // event.name === "user.created"
 * // event.payload.email === "alice@example.com"  ← fully typed
 */
export function parseEvent(raw: unknown): Event {
  const obj = assertPlainObject(raw, "root");

  const id = assertString(obj.id, "id");

  const name = obj.name;
  if (!isEventName(name)) {
    throw new EventParseError(
      `must be one of: ${[...KNOWN_EVENT_NAMES].join(", ")}`,
      "name",
      name
    );
  }

  const timestamp = parseTimestamp(obj.timestamp, "timestamp");
  const timestampRaw =
    obj.timestamp instanceof Date
      ? obj.timestamp.toISOString()
      : String(obj.timestamp);

  const rawPayload = assertPlainObject(obj.payload, "payload");

  // Cast is safe: the validator for `name` returns exactly EventPayloadMap[name].
  const payload = (payloadValidators[name] as PayloadValidator<typeof name>)(
    rawPayload
  );

  const metadata =
    obj.metadata !== undefined
      ? assertPlainObject(obj.metadata, "metadata")
      : undefined;

  return {
    id,
    name,
    timestamp,
    timestampRaw,
    payload,
    metadata,
  } as Event; // discriminated union resolved at runtime
}
```

