## Usage Examples

```typescript
// ── Happy path ────────────────────────────────────────────────────────────────
const event = parseEvent({
  id: "evt_001",
  name: "user.created",
  timestamp: "2024-06-01T12:00:00.000Z",
  payload: { userId: "u_1", email: "alice@example.com", role: "admin" },
  metadata: { source: "auth-service", traceId: "abc-123" },
});

console.log(event.name);            // "user.created"
console.log(event.payload.email);   // "alice@example.com"  ← typed!
console.log(event.timestamp);       // Date object

// ── Narrowing with a type guard ───────────────────────────────────────────────
function handleEvent(e: Event): void {
  switch (e.name) {
    case "user.created":
      console.log("New user:", e.payload.email); // payload fully typed here
      break;
    case "payment.failed":
      console.error("Payment error:", e.payload.errorCode);
      break;
    default:
      console.log("Unhandled event:", e.name);
  }
}

handleEvent(event);

// ── Error cases ───────────────────────────────────────────────────────────────
try {
  parseEvent({ id: "x", name: "unknown.event", timestamp: new Date(), payload: {} });
} catch (err) {
  if (err instanceof EventParseError) {
    console.error(err.message);
    // [EventParseError] name: must be one of: user.created, ... (received: "unknown.event")
  }
}
```

