## Key Design Decisions

| Decision | Rationale |
|---|---|
| **Discriminated union** (`Event<N>`) | TypeScript narrows `payload` automatically after checking `name` |
| **`EventPayloadMap`** | Single source of truth – add a new event in one place |
| **`payloadValidators` map** | Exhaustive at compile time; adding a new `EventName` forces a new validator |
| **`EventParseError`** with `field` | Callers can programmatically identify which field failed |
| **`timestampRaw`** | Preserves the original string for serialisation without re-formatting |
| **No external dependencies** | Zero-dependency runtime validation; swap in Zod/Valibot if preferred |

## Event Type Declaration & Parser

### Types

```typescript
// Event payload can be any JSON-serializable value
type JsonPrimitive = string | number | boolean | null;
type JsonValue =
  | JsonPrimitive
  | JsonValue[]
  | { [key: string]: JsonValue };

interface Event {
  name: string;
  timestamp: Date;
  payload: Record<string, JsonValue>;
}
```

### Parser Implementation

```typescript
class EventParseError extends Error {
  constructor(
    message: string,
    public readonly field: string,
    public readonly received: unknown
  ) {
    super(`[EventParseError] ${field}: ${message}. Received: ${JSON.stringify(received)}`);
    this.name = "EventParseError";
  }
}

// ─── Field validators ────────────────────────────────────────────────────────

function assertPlainObject(
  value: unknown,
  field: string
): asserts value is Record<string, unknown> {
  if (
    value === null ||
    typeof value !== "object" ||
    Array.isArray(value)
  ) {
    throw new EventParseError("must be a plain object", field, value);
  }
}

function parseName(raw: unknown): string {
  if (typeof raw !== "string") {
    throw new EventParseError("must be a string", "name", raw);
  }
  const trimmed = raw.trim();
  if (trimmed.length === 0) {
    throw new EventParseError("must not be empty", "name", raw);
  }
  return trimmed;
}

function parseTimestamp(raw: unknown): Date {
  if (raw instanceof Date) {
    if (isNaN(raw.getTime())) {
      throw new EventParseError("invalid Date object", "timestamp", raw);
    }
    return raw;
  }

  if (typeof raw === "string" || typeof raw === "number") {
    const date = new Date(raw);
    if (isNaN(date.getTime())) {
      throw new EventParseError(
        "cannot be parsed into a valid date",
        "timestamp",
        raw
      );
    }
    return date;
  }

  throw new EventParseError(
    "must be a Date, ISO string, or Unix timestamp (ms)",
    "timestamp",
    raw
  );
}

function isJsonValue(value: unknown): value is JsonValue {
  if (value === null) return true;

  switch (typeof value) {
    case "string":
    case "number":
    case "boolean":
      return true;
    case "object":
      if (Array.isArray(value)) {
        return value.every(isJsonValue);
      }
      return (
        value !== null &&
        Object.values(value as Record<string, unknown>).every(isJsonValue)
      );
    default:
      return false;
  }
}

function parsePayload(raw: unknown): Record<string, JsonValue> {
  // Default to empty payload if omitted
  if (raw === undefined || raw === null) {
    return {};
  }

  assertPlainObject(raw, "payload");

  const payload: Record<string, JsonValue> = {};

  for (const [key, value] of Object.entries(raw)) {
    if (!isJsonValue(value)) {
      throw new EventParseError(
        `value at key "${key}" is not JSON-serializable`,
        "payload",
        value
      );
    }
    payload[key] = value;
  }

  return payload;
}

// ─── Main parser ─────────────────────────────────────────────────────────────

function parseEvent(raw: unknown): Event {
  assertPlainObject(raw, "event");

  return {
    name:      parseName(raw["name"]),
    timestamp: parseTimestamp(raw["timestamp"]),
    payload:   parsePayload(raw["payload"]),
  };
}
```

### Usage Examples

```typescript
// ✅ Valid – ISO string timestamp
const e1 = parseEvent({
  name: "user.signup",
  timestamp: "2024-06-01T12:00:00Z",
  payload: { userId: "abc123", plan: "pro", trialDays: 14 },
});
console.log(e1);
// { name: 'user.signup', timestamp: Date, payload: { userId: 'abc123', ... } }

// ✅ Valid – numeric timestamp, no payload
const e2 = parseEvent({
  name: "ping",
  timestamp: Date.now(),
});
console.log(e2.payload); // {}

// ✅ Valid – Date object
const e3 = parseEvent({
  name: "order.placed",
  timestamp: new Date(),
  payload: { items: ["a", "b"], total: 99.99, metadata: null },
});

// ❌ Missing name → EventParseError: [EventParseError] name: must be a string
parseEvent({ timestamp: new Date() });

// ❌ Non-serializable payload value → EventParseError
parseEvent({
  name: "bad",
  timestamp: new Date(),
  payload: { fn: () => {} },   // functions are not JSON-serializable
});
```

### Key Design Decisions

| Decision | Rationale |
|---|---|
| `EventParseError` extends `Error` | Distinguishes parse failures from other runtime errors; includes `field` for programmatic handling |
| `timestamp` accepts `Date \| string \| number` | Handles the most common real-world formats without being overly strict |
| `payload` defaults to `{}` when absent | Events often have no extra data; forcing the field adds noise |
| `isJsonValue` recursive guard | Ensures the payload is truly serializable before accepting it |
| Separate field parsers | Each validator is independently testable and reusable |

## Event Type Declaration & Parser

### Types

```typescript
// Event payload can be any JSON-serializable value
type JsonPrimitive = string | number | boolean | null;
type JsonArray = JsonValue[];
type JsonObject = { [key: string]: JsonValue };
type JsonValue = JsonPrimitive | JsonArray | JsonObject;

interface Event {
  name: string;
  timestamp: Date;
  payload: JsonObject;
}
```

### Implementation

```typescript
// ─── Custom Error ────────────────────────────────────────────────────────────

class EventParseError extends Error {
  constructor(
    message: string,
    public readonly field: string,
    public readonly received: unknown
  ) {
    super(`[EventParseError] ${field}: ${message}. Received: ${JSON.stringify(received)}`);
    this.name = "EventParseError";
  }
}

// ─── Guards ──────────────────────────────────────────────────────────────────

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isJsonObject(value: unknown): value is JsonObject {
  if (!isPlainObject(value)) return false;

  return Object.values(value).every((v) => isJsonValue(v));
}

function isJsonValue(value: unknown): value is JsonValue {
  if (value === null) return true;
  if (typeof value === "string") return true;
  if (typeof value === "number") return true;
  if (typeof value === "boolean") return true;
  if (Array.isArray(value)) return value.every(isJsonValue);
  if (isPlainObject(value)) return Object.values(value).every(isJsonValue);
  return false;
}

// ─── Field Parsers ───────────────────────────────────────────────────────────

function parseName(raw: unknown): string {
  if (typeof raw !== "string") {
    throw new EventParseError("must be a string", "name", raw);
  }

  const trimmed = raw.trim();

  if (trimmed.length === 0) {
    throw new EventParseError("must not be empty", "name", raw);
  }

  return trimmed;
}

function parseTimestamp(raw: unknown): Date {
  // Accept Date objects directly
  if (raw instanceof Date) {
    if (isNaN(raw.getTime())) {
      throw new EventParseError("is an invalid Date object", "timestamp", raw);
    }
    return raw;
  }

  // Accept ISO strings or Unix epoch numbers
  if (typeof raw === "string" || typeof raw === "number") {
    const date = new Date(raw);
    if (isNaN(date.getTime())) {
      throw new EventParseError(
        "could not be parsed into a valid date",
        "timestamp",
        raw
      );
    }
    return date;
  }

  throw new EventParseError(
    "must be a Date, ISO string, or Unix timestamp (number)",
    "timestamp",
    raw
  );
}

function parsePayload(raw: unknown): JsonObject {
  if (!isJsonObject(raw)) {
    throw new EventParseError(
      "must be a plain JSON object (no functions, undefined, or circular refs)",
      "payload",
      raw
    );
  }

  return raw;
}

// ─── Main Parser ─────────────────────────────────────────────────────────────

function parseEvent(raw: unknown): Event {
  if (!isPlainObject(raw)) {
    throw new EventParseError(
      "event must be a plain object",
      "root",
      raw
    );
  }

  return {
    name:      parseName(raw["name"]),
    timestamp: parseTimestamp(raw["timestamp"]),
    payload:   parsePayload(raw["payload"]),
  };
}
```

### Usage Examples

```typescript
// ✅ Valid — ISO string timestamp
const e1 = parseEvent({
  name: "user.signup",
  timestamp: "2024-06-01T12:00:00.000Z",
  payload: { userId: 42, plan: "pro" },
});
console.log(e1);
// { name: 'user.signup', timestamp: Date(...), payload: { userId: 42, plan: 'pro' } }

// ✅ Valid — numeric epoch timestamp
const e2 = parseEvent({
  name: "order.placed",
  timestamp: 1717243200000,
  payload: { orderId: "abc-123", total: 99.99 },
});

// ✅ Valid — Date object
const e3 = parseEvent({
  name: "session.end",
  timestamp: new Date(),
  payload: {},
});

// ❌ Missing name → EventParseError: [EventParseError] name: must be a string
parseEvent({ timestamp: new Date(), payload: {} });

// ❌ Bad timestamp → EventParseError: [EventParseError] timestamp: could not be parsed
parseEvent({ name: "x", timestamp: "not-a-date", payload: {} });

// ❌ Payload with function → EventParseError: [EventParseError] payload: must be a plain JSON object
parseEvent({ name: "x", timestamp: new Date(), payload: { fn: () => {} } });
```

---

### Key Design Decisions

| Decision | Rationale |
|---|---|
| `JsonObject` payload type | Ensures payload is always serializable; rejects `undefined`, functions, and class instances |
| `Date` as `timestamp` type | Normalizes all input formats (string / number / Date) into a single canonical type |
| Dedicated `EventParseError` | Carries `field` and `received` for structured error handling / logging |
| Field parsers are separate functions | Each is independently testable and reusable |
| `isPlainObject` guard | Safely narrows `unknown` before property access, avoiding prototype-chain surprises |

## Event Type Declaration & Parser

### Types

```typescript
// Event payload can be any JSON-serializable value
type JsonPrimitive = string | number | boolean | null;
type JsonArray = JsonValue[];
type JsonObject = { [key: string]: JsonValue };
type JsonValue = JsonPrimitive | JsonArray | JsonObject;

interface Event<P extends JsonValue = JsonValue> {
  name: string;
  timestamp: Date;
  payload: P;
}
```

### Implementation

```typescript
// ─── Custom Error ────────────────────────────────────────────────────────────

class EventParseError extends Error {
  constructor(
    message: string,
    public readonly field: string,
    public readonly received: unknown
  ) {
    super(`[EventParseError] ${field}: ${message}. Received: ${JSON.stringify(received)}`);
    this.name = "EventParseError";
  }
}

// ─── Guards ──────────────────────────────────────────────────────────────────

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isJsonValue(value: unknown): value is JsonValue {
  if (value === null) return true;

  switch (typeof value) {
    case "string":
    case "number":
    case "boolean":
      return true;

    case "object":
      if (Array.isArray(value)) {
        return value.every(isJsonValue);
      }
      return (
        isPlainObject(value) &&
        Object.values(value).every(isJsonValue)
      );

    default:
      return false;
  }
}

// ─── Timestamp Parser ────────────────────────────────────────────────────────

function parseTimestamp(value: unknown, field: string): Date {
  if (value instanceof Date) {
    if (isNaN(value.getTime())) {
      throw new EventParseError("invalid Date object", field, value);
    }
    return value;
  }

  if (typeof value === "string" || typeof value === "number") {
    const date = new Date(value);
    if (isNaN(date.getTime())) {
      throw new EventParseError("cannot be parsed as a date", field, value);
    }
    return date;
  }

  throw new EventParseError(
    "must be a Date, ISO string, or Unix timestamp (ms)",
    field,
    value
  );
}

// ─── Main Parser ─────────────────────────────────────────────────────────────

function parseEvent(raw: unknown): Event {
  if (!isPlainObject(raw)) {
    throw new EventParseError(
      "event must be a plain object",
      "root",
      raw
    );
  }

  // ── name ──────────────────────────────────────────────────────────────────
  const { name, timestamp, payload } = raw;

  if (typeof name !== "string") {
    throw new EventParseError("must be a string", "name", name);
  }

  const trimmedName = name.trim();
  if (trimmedName.length === 0) {
    throw new EventParseError("must not be empty", "name", name);
  }

  // ── timestamp ─────────────────────────────────────────────────────────────
  const parsedTimestamp = parseTimestamp(timestamp, "timestamp");

  // ── payload ───────────────────────────────────────────────────────────────
  if (!isJsonValue(payload)) {
    throw new EventParseError(
      "must be a JSON-serializable value (no undefined, functions, symbols, etc.)",
      "payload",
      payload
    );
  }

  return {
    name: trimmedName,
    timestamp: parsedTimestamp,
    payload,
  };
}
```

### Usage Examples

