### Key Design Decisions

| Decision | Rationale |
|---|---|
| `JsonValue` recursive type | Ensures payload is always serializable / round-trippable |
| `Date` output for timestamp | Consumers get a real `Date`, not a raw string |
| Accepts `string \| number \| Date` as timestamp input | Handles ISO strings, Unix ms, and native `Date` objects |
| `EventParseError` with `field` property | Structured errors make programmatic handling easy |
| Generic `Event<P>` | Callers can narrow the payload type when they know it upfront |

## Event Type Declaration & Parser

```typescript
// ─── Types ────────────────────────────────────────────────────────────────────

/** Allowed primitive payload values */
type PayloadValue =
  | string
  | number
  | boolean
  | null
  | PayloadValue[]
  | { [key: string]: PayloadValue };

/** The canonical Event shape returned by parseEvent */
interface Event {
  /** Human-readable event identifier, e.g. "user.signed_up" */
  name: string;
  /** Normalised UTC timestamp (always a valid Date) */
  timestamp: Date;
  /** Arbitrary structured data attached to the event */
  payload: Record<string, PayloadValue>;
}

// ─── Custom Error ─────────────────────────────────────────────────────────────

class EventParseError extends Error {
  constructor(
    message: string,
    public readonly field: string,
    public readonly received: unknown
  ) {
    super(`[EventParseError] ${field}: ${message} (received: ${JSON.stringify(received)})`);
    this.name = "EventParseError";
  }
}

// ─── Guards & Helpers ─────────────────────────────────────────────────────────

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function parseName(raw: unknown): string {
  if (typeof raw !== "string") {
    throw new EventParseError("must be a string", "name", raw);
  }

  const trimmed = raw.trim();

  if (trimmed.length === 0) {
    throw new EventParseError("must not be empty", "name", raw);
  }

  // Optional: enforce a naming convention like "category.action"
  if (!/^[a-z][a-z0-9]*(\.[a-z][a-z0-9]*)*$/.test(trimmed)) {
    throw new EventParseError(
      'must match pattern "category.action" (lowercase alphanumeric, dot-separated)',
      "name",
      raw
    );
  }

  return trimmed;
}

function parseTimestamp(raw: unknown): Date {
  let date: Date;

  if (raw instanceof Date) {
    date = raw;
  } else if (typeof raw === "string" || typeof raw === "number") {
    date = new Date(raw);
  } else {
    throw new EventParseError(
      "must be a Date, ISO string, or Unix timestamp (ms)",
      "timestamp",
      raw
    );
  }

  if (isNaN(date.getTime())) {
    throw new EventParseError("resolved to an invalid date", "timestamp", raw);
  }

  return date;
}

function parsePayloadValue(value: unknown, path: string): PayloadValue {
  if (value === null) return null;

  switch (typeof value) {
    case "string":
    case "number":
    case "boolean":
      return value;

    case "object":
      if (Array.isArray(value)) {
        return value.map((item, i) => parsePayloadValue(item, `${path}[${i}]`));
      }

      if (isPlainObject(value)) {
        return Object.fromEntries(
          Object.entries(value).map(([k, v]) => [k, parsePayloadValue(v, `${path}.${k}`)])
        );
      }

      throw new EventParseError(
        "unsupported object type in payload",
        path,
        value
      );

    default:
      throw new EventParseError(
        `unsupported type "${typeof value}" in payload`,
        path,
        value
      );
  }
}

function parsePayload(raw: unknown): Record<string, PayloadValue> {
  // Accept missing / undefined payload as empty object
  if (raw === undefined || raw === null) return {};

  if (!isPlainObject(raw)) {
    throw new EventParseError("must be a plain object", "payload", raw);
  }

  return Object.fromEntries(
    Object.entries(raw).map(([key, value]) => [
      key,
      parsePayloadValue(value, `payload.${key}`),
    ])
  );
}

// ─── Main Parser ──────────────────────────────────────────────────────────────

/**
 * Parses an unknown value into a strongly-typed `Event`.
 *
 * @throws {EventParseError} if any field is missing or malformed.
 *
 * @example
 * const event = parseEvent({
 *   name: "user.signed_up",
 *   timestamp: "2024-06-01T12:00:00Z",
 *   payload: { userId: "abc123", plan: "pro" },
 * });
 */
function parseEvent(raw: unknown): Event {
  if (!isPlainObject(raw)) {
    throw new EventParseError("event must be a plain object", "root", raw);
  }

  return {
    name:      parseName(raw["name"]),
    timestamp: parseTimestamp(raw["timestamp"]),
    payload:   parsePayload(raw["payload"]),
  };
}

// ─── Example Usage ────────────────────────────────────────────────────────────

const validRaw = {
  name: "order.placed",
  timestamp: "2024-06-01T12:00:00Z",
  payload: {
    orderId: "ord_001",
    total: 99.99,
    items: [{ sku: "ABC", qty: 2 }],
    express: true,
    coupon: null,
  },
};

const event = parseEvent(validRaw);
console.log(event);
/*
{
  name: 'order.placed',
  timestamp: 2024-06-01T12:00:00.000Z,   ← real Date object
  payload: {
    orderId: 'ord_001',
    total: 99.99,
    items: [ { sku: 'ABC', qty: 2 } ],
    express: true,
    coupon: null
  }
}
*/

// Error cases
try {
  parseEvent({ name: "BAD NAME", timestamp: Date.now(), payload: {} });
} catch (e) {
  console.error((e as EventParseError).message);
  // [EventParseError] name: must match pattern … (received: "BAD NAME")
}

try {
  parseEvent({ name: "user.login", timestamp: "not-a-date", payload: {} });
} catch (e) {
  console.error((e as EventParseError).message);
  // [EventParseError] timestamp: resolved to an invalid date (received: "not-a-date")
}
```

