 * Type guard: checks if a value is a plain object (not null, not array).
 */
function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * Type guard: checks if a value is a valid JsonValue.
 */
function isJsonValue(value: unknown): value is JsonValue {
  if (value === null) return true;

  switch (typeof value) {
    case "string":
    case "number":
    case "boolean":
      return true;

    case "object":
      if (Array.isArray(value)) {
        return value.every(isJsonValue);
      }
      return (
        isPlainObject(value) &&
        Object.values(value).every(isJsonValue)
      );

    default:
      return false;
  }
}

/**
 * Parses a raw unknown value into a typed Event.
 *
 * Accepts `timestamp` as:
 *   - a Date instance
 *   - an ISO 8601 string
 *   - a Unix timestamp (number, milliseconds)
 *
 * @throws {EventParseError} if any required field is missing or invalid.
 */
function parseEvent(raw: unknown): Event {
  // ── 1. Top-level must be a plain object ──────────────────────────────────
  if (!isPlainObject(raw)) {
    throw new EventParseError("must be a plain object", "root", raw);
  }

  // ── 2. Validate `name` ───────────────────────────────────────────────────
  const { name, timestamp, payload } = raw;

  if (typeof name !== "string" || name.trim() === "") {
    throw new EventParseError(
      "must be a non-empty string",
      "name",
      name
    );
  }

  // ── 3. Validate & coerce `timestamp` ─────────────────────────────────────
  let parsedTimestamp: Date;

  if (timestamp instanceof Date) {
    parsedTimestamp = timestamp;
  } else if (typeof timestamp === "string" || typeof timestamp === "number") {
    parsedTimestamp = new Date(timestamp);
  } else {
    throw new EventParseError(
      "must be a Date, ISO string, or Unix ms number",
      "timestamp",
      timestamp
    );
  }

  if (isNaN(parsedTimestamp.getTime())) {
    throw new EventParseError(
      "resolved to an invalid date",
      "timestamp",
      timestamp
    );
  }

  // ── 4. Validate `payload` ────────────────────────────────────────────────
  if (!isPlainObject(payload)) {
    throw new EventParseError(
      "must be a plain JSON object",
      "payload",
      payload
    );
  }

  if (!isJsonValue(payload)) {
    throw new EventParseError(
      "contains non-serializable values",
      "payload",
      payload
    );
  }

  // ── 5. Return fully-typed Event ──────────────────────────────────────────
  return {
    name: name.trim(),
    timestamp: parsedTimestamp,
    payload,
  };
}
```

### Usage Examples

```typescript
// ✅ Valid — ISO string timestamp
const e1 = parseEvent({
  name: "user.signup",
  timestamp: "2024-06-01T12:00:00.000Z",
  payload: { userId: "abc123", plan: "pro" },
});
// e1: Event<JsonObject>
// e1.timestamp → Date object
// e1.payload   → { userId: "abc123", plan: "pro" }

// ✅ Valid — numeric timestamp
const e2 = parseEvent({
  name: "order.placed",
  timestamp: 1717243200000,
  payload: { orderId: 42, items: ["book", "pen"] },
});

// ✅ Valid — Date instance
const e3 = parseEvent({
  name: "session.end",
  timestamp: new Date(),
  payload: { duration: 300, reason: null },
});

// ❌ Missing name → EventParseError: [EventParseError] name: must be a non-empty string
parseEvent({ timestamp: new Date(), payload: {} });

// ❌ Bad timestamp → EventParseError: [EventParseError] timestamp: resolved to an invalid date
parseEvent({ name: "test", timestamp: "not-a-date", payload: {} });

// ❌ Payload is an array, not an object
parseEvent({ name: "test", timestamp: new Date(), payload: [1, 2, 3] });
```

### Key Design Decisions

| Decision | Rationale |
|---|---|
| `JsonValue` recursive type | Ensures payload is fully serializable at the type level |
| `isJsonValue` runtime guard | Catches `undefined`, functions, `Symbol` etc. that bypass TS |
| `EventParseError` with `field` | Structured errors make debugging and logging easier |
| Timestamp coercion | Accepts `Date`, ISO string, or Unix ms — common real-world formats |
| `name.trim()` | Normalises whitespace-only strings and leading/trailing spaces |

