### Implementation

```typescript
class EventParseError extends Error {
  constructor(
    message: string,
    public readonly field: string,
    public readonly received: unknown
  ) {
    super(`[EventParseError] ${field}: ${message}. Received: ${JSON.stringify(received)}`);
    this.name = "EventParseError";
  }
}

/**
 * Type guard: checks if a value is a plain object (not null, not array).
 */
function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * Type guard: checks if a value is a valid JsonValue.
 */
function isJsonValue(value: unknown): value is JsonValue {
  if (value === null) return true;

  switch (typeof value) {
    case "string":
    case "number":
    case "boolean":
      return true;
    case "object":
      if (Array.isArray(value)) {
        return value.every(isJsonValue);
      }
      return (
        isPlainObject(value) &&
        Object.values(value).every(isJsonValue)
      );
    default:
      return false;
  }
}

/**
 * Parses a raw unknown value into a typed Event.
 *
 * Accepts:
 *  - timestamp as ISO string, Unix ms number, or Date instance
 *  - payload as any JSON-serializable object
 *
 * Throws EventParseError on invalid input.
 */
function parseEvent(raw: unknown): Event {
  // ── 1. Top-level must be a plain object ──────────────────────────────────
  if (!isPlainObject(raw)) {
    throw new EventParseError("must be a plain object", "root", raw);
  }

  // ── 2. Validate `name` ───────────────────────────────────────────────────
  const { name, timestamp, payload } = raw;

  if (typeof name !== "string" || name.trim() === "") {
    throw new EventParseError(
      "must be a non-empty string",
      "name",
      name
    );
  }

  // ── 3. Validate & coerce `timestamp` ─────────────────────────────────────
  let parsedTimestamp: Date;

  if (timestamp instanceof Date) {
    parsedTimestamp = timestamp;
  } else if (typeof timestamp === "string") {
    const d = new Date(timestamp);
    if (isNaN(d.getTime())) {
      throw new EventParseError(
        "string is not a valid date",
        "timestamp",
        timestamp
      );
    }
    parsedTimestamp = d;
  } else if (typeof timestamp === "number") {
    if (!Number.isFinite(timestamp) || timestamp < 0) {
      throw new EventParseError(
        "number must be a finite non-negative Unix ms value",
        "timestamp",
        timestamp
      );
    }
    parsedTimestamp = new Date(timestamp);
  } else {
    throw new EventParseError(
      "must be a Date, ISO string, or Unix ms number",
      "timestamp",
      timestamp
    );
  }

  // ── 4. Validate `payload` ────────────────────────────────────────────────
  if (!isPlainObject(payload)) {
    throw new EventParseError(
      "must be a plain JSON object",
      "payload",
      payload
    );
  }

  if (!isJsonValue(payload)) {
    throw new EventParseError(
      "contains non-serializable values",
      "payload",
      payload
    );
  }

  // ── 5. Return typed Event ────────────────────────────────────────────────
  return {
    name: name.trim(),
    timestamp: parsedTimestamp,
    payload,
  };
}
```

