### Core Parser

```typescript
// ─── Parser ──────────────────────────────────────────────────────────────────

/**
 * Parses an unknown value into a typed `Event`.
 *
 * Accepted timestamp formats
 *   • ISO 8601 string  → "2024-06-01T12:00:00Z"
 *   • Unix ms number   → 1717243200000
 *   • Date instance    → new Date(...)
 *
 * @throws {EventParseError} on any validation failure
 */
function parseEvent(raw: unknown): Event {
  // ── 1. Must be a plain object ─────────────────────────────────────────────
  if (!isPlainObject(raw)) {
    throw new EventParseError("must be a plain object", "root", raw);
  }

  // ── 2. name ───────────────────────────────────────────────────────────────
  const { name, timestamp, payload } = raw;

  if (typeof name !== "string" || name.trim() === "") {
    throw new EventParseError(
      "must be a non-empty string",
      "name",
      name
    );
  }

  // ── 3. timestamp ──────────────────────────────────────────────────────────
  let parsedDate: Date;

  if (timestamp instanceof Date) {
    parsedDate = timestamp;
  } else if (typeof timestamp === "string" || typeof timestamp === "number") {
    parsedDate = new Date(timestamp);
  } else {
    throw new EventParseError(
      "must be a Date, ISO string, or Unix ms number",
      "timestamp",
      timestamp
    );
  }

  if (isNaN(parsedDate.getTime())) {
    throw new EventParseError(
      "resolves to an invalid date",
      "timestamp",
      timestamp
    );
  }

  // ── 4. payload ────────────────────────────────────────────────────────────
  if (payload === undefined) {
    throw new EventParseError("field is required", "payload", payload);
  }

  if (!isPayloadRecord(payload)) {
    throw new EventParseError(
      "must be a plain object with primitive-compatible values",
      "payload",
      payload
    );
  }

  // ── 5. Return typed Event ─────────────────────────────────────────────────
  return {
    name: name.trim(),
    timestamp: parsedDate,
    payload,
  };
}
```

