### Parser

```typescript
// parseEvent.ts

import { type Event, type EventPayload } from "./types/event";
import { ParseError } from "./errors/ParseError";

// ─── Internal guards ────────────────────────────────────────────────────────

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return (
    typeof value === "object" &&
    value !== null &&
    !Array.isArray(value) &&
    Object.getPrototypeOf(value) === Object.prototype
  );
}

function parseName(raw: unknown): string {
  if (typeof raw !== "string") {
    throw new ParseError("must be a string", "name", raw);
  }
  const trimmed = raw.trim();
  if (trimmed.length === 0) {
    throw new ParseError("must not be empty", "name", raw);
  }
  return trimmed;
}

function parseTimestamp(raw: unknown): Date {
  // Accept: Date instance | ISO string | Unix ms number
  if (raw instanceof Date) {
    if (isNaN(raw.getTime())) {
      throw new ParseError("Invalid Date object", "timestamp", raw);
    }
    return raw;
  }

  if (typeof raw === "string" || typeof raw === "number") {
    const date = new Date(raw);
    if (isNaN(date.getTime())) {
      throw new ParseError(
        "cannot be converted to a valid Date",
        "timestamp",
        raw,
      );
    }
    return date;
  }

  throw new ParseError(
    "must be a Date, ISO string, or Unix timestamp (ms)",
    "timestamp",
    raw,
  );
}

function parsePayload(raw: unknown): EventPayload {
  // Default to empty payload when omitted
  if (raw === undefined || raw === null) {
    return {};
  }
  if (!isPlainObject(raw)) {
    throw new ParseError("must be a plain object", "payload", raw);
  }
  return raw;
}

// ─── Public API ─────────────────────────────────────────────────────────────

/**
 * Parses an unknown value into a strongly-typed {@link Event}.
 *
 * @param raw - Any value (e.g. JSON.parse result, network response body).
 * @returns A validated {@link Event} object.
 * @throws {ParseError} when a required field is missing or has the wrong type.
 *
 * @example
 * const event = parseEvent({
 *   name: "order.placed",
 *   timestamp: "2024-06-01T12:00:00Z",
 *   payload: { orderId: "abc-123", total: 99.99 },
 * });
 */
export function parseEvent(raw: unknown): Event {
  if (!isPlainObject(raw)) {
    throw new ParseError(
      "event must be a plain object",
      "<root>",
      raw,
    );
  }

  return {
    name: parseName(raw["name"]),
    timestamp: parseTimestamp(raw["timestamp"]),
    payload: parsePayload(raw["payload"]),
  };
}
```

