### Key Design Decisions

| Decision | Rationale |
|---|---|
| `(string & {})` in `EventName` | Preserves autocomplete for known names while allowing arbitrary strings |
| `isPlainObject` prototype check | Rejects `null`, arrays, class instances, and other non-plain objects |
| `Date \| string \| number` for timestamp | Matches real-world inputs (JSON has no `Date` type, so strings/numbers are common) |
| `payload` defaults to `{}` | Events without data are valid; avoids forcing callers to pass `null` |
| `ParseError` with `field` + `received` | Makes debugging easy; field path pinpoints exactly what failed |

## Event Type Declaration & Parser

```typescript
// ─── Types ────────────────────────────────────────────────────────────────────

/** Allowed primitive payload values */
type PayloadValue =
  | string
  | number
  | boolean
  | null
  | PayloadValue[]
  | { [key: string]: PayloadValue };

/** The canonical, strongly-typed Event shape */
interface Event {
  /** Human-readable event identifier, e.g. "user.signed_up" */
  name: string;
  /** Normalised UTC timestamp (always a valid Date) */
  timestamp: Date;
  /** Arbitrary structured data attached to the event */
  payload: Record<string, PayloadValue>;
}

// ─── Custom Error ─────────────────────────────────────────────────────────────

class EventParseError extends Error {
  constructor(
    message: string,
    public readonly field: string,
    public readonly received: unknown
  ) {
    super(`[EventParseError] ${field}: ${message} (received: ${JSON.stringify(received)})`);
    this.name = "EventParseError";
  }
}

// ─── Internal Helpers ─────────────────────────────────────────────────────────

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * Parse a timestamp that may arrive as:
 *  - a Date object
 *  - an ISO-8601 string
 *  - a Unix epoch number (seconds or milliseconds)
 */
function parseTimestamp(raw: unknown, field: string): Date {
  if (raw instanceof Date) {
    if (isNaN(raw.getTime())) throw new EventParseError("invalid Date object", field, raw);
    return raw;
  }

  if (typeof raw === "string") {
    const d = new Date(raw);
    if (isNaN(d.getTime())) throw new EventParseError("unparseable date string", field, raw);
    return d;
  }

  if (typeof raw === "number") {
    // Heuristic: treat numbers < 1e12 as Unix seconds, otherwise milliseconds
    const ms = raw < 1e12 ? raw * 1_000 : raw;
    const d = new Date(ms);
    if (isNaN(d.getTime())) throw new EventParseError("invalid numeric timestamp", field, raw);
    return d;
  }

  throw new EventParseError("must be a Date, ISO string, or epoch number", field, raw);
}

/** Recursively validate that a value conforms to PayloadValue */
function parsePayloadValue(value: unknown, path: string): PayloadValue {
  if (value === null) return null;

  switch (typeof value) {
    case "string":
    case "number":
    case "boolean":
      return value;

    case "object":
      if (Array.isArray(value)) {
        return value.map((item, i) => parsePayloadValue(item, `${path}[${i}]`));
      }
      if (isPlainObject(value)) {
        return Object.fromEntries(
          Object.entries(value).map(([k, v]) => [k, parsePayloadValue(v, `${path}.${k}`)])
        );
      }
      throw new EventParseError("unsupported object type in payload", path, value);

    default:
      throw new EventParseError(
        `unsupported type "${typeof value}" in payload`,
        path,
        value
      );
  }
}

function parsePayload(raw: unknown, field: string): Record<string, PayloadValue> {
  if (!isPlainObject(raw)) {
    throw new EventParseError("must be a plain object", field, raw);
  }

  return Object.fromEntries(
    Object.entries(raw).map(([k, v]) => [k, parsePayloadValue(v, `${field}.${k}`)])
  );
}

// ─── Main Parser ──────────────────────────────────────────────────────────────

/**
 * Parse an unknown value into a strongly-typed `Event`.
 *
 * Accepts objects of the shape:
 * ```json
 * {
 *   "name":      "user.signed_up",
 *   "timestamp": "2024-06-01T12:00:00Z",   // or Date | epoch number
 *   "payload":   { "userId": 42, "plan": "pro" }
 * }
 * ```
 *
 * @throws {EventParseError} if any field is missing or has an invalid type.
 */
function parseEvent(raw: unknown): Event {
  if (!isPlainObject(raw)) {
    throw new EventParseError("event must be a plain object", "root", raw);
  }

  // ── name ──────────────────────────────────────────────────────────────────
  const { name, timestamp, payload } = raw;

  if (typeof name !== "string" || name.trim() === "") {
    throw new EventParseError("must be a non-empty string", "name", name);
  }

  // ── timestamp ─────────────────────────────────────────────────────────────
  const parsedTimestamp = parseTimestamp(timestamp, "timestamp");

  // ── payload ───────────────────────────────────────────────────────────────
  // Default to empty object when payload is absent
  const parsedPayload = parsePayload(
    payload !== undefined ? payload : {},
    "payload"
  );

  return {
    name: name.trim(),
    timestamp: parsedTimestamp,
    payload: parsedPayload,
  };
}

// ─── Usage Examples ───────────────────────────────────────────────────────────

// ✅ Valid – ISO string timestamp
const e1 = parseEvent({
  name: "user.signed_up",
  timestamp: "2024-06-01T12:00:00Z",
  payload: { userId: 42, plan: "pro", active: true, tags: ["new", "trial"] },
});
console.log(e1);
// { name: 'user.signed_up', timestamp: 2024-06-01T12:00:00.000Z, payload: { userId: 42, ... } }

// ✅ Valid – epoch seconds
const e2 = parseEvent({ name: "page.viewed", timestamp: 1_717_243_200, payload: {} });
console.log(e2.timestamp); // 2024-06-01T12:00:00.000Z

// ✅ Valid – Date object, no payload key (defaults to {})
const e3 = parseEvent({ name: "app.started", timestamp: new Date() });
console.log(e3.payload); // {}

// ❌ Invalid – triggers EventParseError
try {
  parseEvent({ name: "", timestamp: "2024-06-01", payload: {} });
} catch (err) {
  console.error((err as EventParseError).message);
  // [EventParseError] name: must be a non-empty string (received: "")
}
```

---

## Key Design Decisions

| Concern | Choice | Reason |
|---|---|---|
| **Payload typing** | Recursive `PayloadValue` | Handles arbitrary nesting without `any` |
| **Timestamp flexibility** | Accepts `Date`, ISO string, epoch (s or ms) | Real-world events arrive in all three forms |
| **Missing payload** | Defaults to `{}` | Many events carry no data; avoids unnecessary strictness |
| **Error type** | Custom `EventParseError` with `field` + `received` | Callers can programmatically inspect *what* failed |
| **No external deps** | Pure TypeScript | Zero-cost, no schema library lock-in |

