### Core Parser

```typescript
/**
 * Parses an unknown value into a strongly-typed Event.
 *
 * Accepts:
 *  - name:      non-empty string
 *  - timestamp: Date | ISO-8601 string | Unix ms number
 *  - payload:   optional plain object (defaults to {})
 *
 * @throws {EventParseError} on invalid input
 */
function parseEvent(raw: unknown): Event {
  // ── 1. Top-level shape ──────────────────────────────────────────────────────
  if (!isPlainObject(raw)) {
    throw new EventParseError("must be a plain object", "root", raw);
  }

  // ── 2. name ─────────────────────────────────────────────────────────────────
  const { name, timestamp, payload } = raw;

  if (typeof name !== "string" || name.trim().length === 0) {
    throw new EventParseError("must be a non-empty string", "name", name);
  }

  // ── 3. timestamp ─────────────────────────────────────────────────────────────
  let parsedTimestamp: Date;

  if (timestamp instanceof Date) {
    parsedTimestamp = timestamp;
  } else if (typeof timestamp === "string") {
    parsedTimestamp = new Date(timestamp);
  } else if (typeof timestamp === "number") {
    parsedTimestamp = new Date(timestamp);
  } else {
    throw new EventParseError(
      "must be a Date, ISO-8601 string, or Unix ms number",
      "timestamp",
      timestamp
    );
  }

  if (isNaN(parsedTimestamp.getTime())) {
    throw new EventParseError("resolved to an invalid Date", "timestamp", timestamp);
  }

  // ── 4. payload ───────────────────────────────────────────────────────────────
  let parsedPayload: EventPayload;

  if (payload === undefined || payload === null) {
    parsedPayload = {};
  } else if (isPlainObject(payload)) {
    parsedPayload = payload;
  } else {
    throw new EventParseError("must be a plain object or omitted", "payload", payload);
  }

  // ── 5. Return typed Event ────────────────────────────────────────────────────
  return {
    name: name.trim(),
    timestamp: parsedTimestamp,
    payload: parsedPayload,
  };
}
```

