### Generic Variant (typed payload)

```typescript
/**
 * Parses and narrows the payload to a specific shape via a user-supplied
 * guard function.
 *
 * @example
 * interface ClickPayload { x: number; y: number }
 *
 * const isClickPayload = (p: unknown): p is ClickPayload =>
 *   isPlainObject(p) && typeof p.x === "number" && typeof p.y === "number";
 *
 * const event = parseEventAs(raw, isClickPayload);
 * // event.payload is ClickPayload ✓
 */
function parseEventAs<P extends EventPayload>(
  raw: unknown,
  payloadGuard: (payload: unknown) => payload is P
): Event<P> {
  const event = parseEvent(raw);

  if (!payloadGuard(event.payload)) {
    throw new EventParseError(
      "payload did not satisfy the provided type guard",
      "payload",
      event.payload
    );
  }

  return event as Event<P>;
}
```

