### Implementation

```typescript
// ─── Custom Error ────────────────────────────────────────────────────────────

class EventParseError extends Error {
  constructor(
    message: string,
    public readonly field: string,
    public readonly received: unknown
  ) {
    super(`[EventParseError] ${field}: ${message}. Received: ${JSON.stringify(received)}`);
    this.name = "EventParseError";
  }
}

// ─── Guard Helpers ───────────────────────────────────────────────────────────

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return (
    typeof value === "object" &&
    value !== null &&
    !Array.isArray(value) &&
    Object.getPrototypeOf(value) === Object.prototype
  );
}

function isPrimitive(value: unknown): value is Primitive {
  return (
    typeof value === "string" ||
    typeof value === "number" ||
    typeof value === "boolean" ||
    value === null
  );
}

function isPayload(value: unknown): value is Payload {
  if (!isPlainObject(value)) return false;

  return Object.entries(value).every(([, v]) => {
    if (isPrimitive(v)) return true;

    if (Array.isArray(v)) {
      return v.every((item) => isPrimitive(item) || isPayload(item));
    }

    return isPayload(v);
  });
}

// ─── Timestamp Parser ────────────────────────────────────────────────────────

function parseTimestamp(raw: unknown, field = "timestamp"): Date {
  if (raw instanceof Date) {
    if (isNaN(raw.getTime())) {
      throw new EventParseError("Invalid Date instance", field, raw);
    }
    return raw;
  }

  if (typeof raw === "string" || typeof raw === "number") {
    const date = new Date(raw);
    if (isNaN(date.getTime())) {
      throw new EventParseError("Cannot parse into a valid Date", field, raw);
    }
    return date;
  }

  throw new EventParseError(
    "Expected a Date, ISO string, or Unix timestamp (ms)",
    field,
    raw
  );
}

// ─── Main Parser ─────────────────────────────────────────────────────────────

function parseEvent(raw: unknown): Event {
  // 1. Must be a plain object
  if (!isPlainObject(raw)) {
    throw new EventParseError("Event must be a plain object", "root", raw);
  }

  // 2. Validate `name`
  const { name, timestamp, payload } = raw;

  if (typeof name !== "string") {
    throw new EventParseError("Must be a non-empty string", "name", name);
  }
  if (name.trim().length === 0) {
    throw new EventParseError("Must not be blank", "name", name);
  }

  // 3. Validate `timestamp`
  const parsedTimestamp = parseTimestamp(timestamp);

  // 4. Validate `payload`
  if (payload === undefined) {
    throw new EventParseError("Field is required", "payload", payload);
  }
  if (!isPayload(payload)) {
    throw new EventParseError(
      "Must be a plain object with primitive/nested-object values",
      "payload",
      payload
    );
  }

  return {
    name: name.trim(),
    timestamp: parsedTimestamp,
    payload,
  };
}
```

