### Implementation

```typescript
class EventParseError extends Error {
  constructor(
    message: string,
    public readonly field: string,
    public readonly received: unknown
  ) {
    super(`[EventParseError] ${field}: ${message}. Received: ${JSON.stringify(received)}`);
    this.name = "EventParseError";
  }
}

// ─── Field validators ────────────────────────────────────────────────────────

function assertPlainObject(
  value: unknown,
  field: string
): asserts value is Record<string, unknown> {
  if (
    value === null ||
    typeof value !== "object" ||
    Array.isArray(value)
  ) {
    throw new EventParseError("must be a plain object", field, value);
  }
}

function parseName(raw: unknown): string {
  if (typeof raw !== "string") {
    throw new EventParseError("must be a string", "name", raw);
  }
  const trimmed = raw.trim();
  if (trimmed.length === 0) {
    throw new EventParseError("must not be empty", "name", raw);
  }
  return trimmed;
}

function parseTimestamp(raw: unknown): Date {
  if (raw instanceof Date) {
    if (isNaN(raw.getTime())) {
      throw new EventParseError("invalid Date object", "timestamp", raw);
    }
    return raw;
  }

  if (typeof raw === "string" || typeof raw === "number") {
    const date = new Date(raw);
    if (isNaN(date.getTime())) {
      throw new EventParseError(
        "cannot be parsed into a valid date",
        "timestamp",
        raw
      );
    }
    return date;
  }

  throw new EventParseError(
    "must be a Date, ISO string, or Unix timestamp (ms)",
    "timestamp",
    raw
  );
}

function parseJsonValue(value: unknown, path: string): JsonValue {
  if (value === null) return null;

  if (
    typeof value === "string" ||
    typeof value === "number" ||
    typeof value === "boolean"
  ) {
    return value;
  }

  if (Array.isArray(value)) {
    return value.map((item, i) => parseJsonValue(item, `${path}[${i}]`));
  }

  if (typeof value === "object") {
    const result: JsonObject = {};
    for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
      result[k] = parseJsonValue(v, `${path}.${k}`);
    }
    return result;
  }

  throw new EventParseError(
    `unsupported value type "${typeof value}"`,
    path,
    value
  );
}

function parsePayload(raw: unknown): JsonObject {
  if (raw === undefined || raw === null) {
    return {}; // default to empty payload
  }

  assertPlainObject(raw, "payload");

  const result: JsonObject = {};
  for (const [key, value] of Object.entries(raw)) {
    result[key] = parseJsonValue(value, `payload.${key}`);
  }
  return result;
}

// ─── Main parser ─────────────────────────────────────────────────────────────

function parseEvent(raw: unknown): Event {
  assertPlainObject(raw, "root");

  return {
    name:      parseName(raw["name"]),
    timestamp: parseTimestamp(raw["timestamp"]),
    payload:   parsePayload(raw["payload"]),
  };
}
```

