### Full Implementation

```typescript
// ─── Types ───────────────────────────────────────────────────────────────────

/** Discriminated union of well-known event names */
type EventName =
  | "user.created"
  | "user.updated"
  | "user.deleted"
  | "order.placed"
  | "order.shipped"
  | "order.cancelled"
  | (string & {}); // allow arbitrary strings while keeping autocomplete

/** Payloads keyed by event name */
interface EventPayloadMap {
  "user.created": { userId: string; email: string };
  "user.updated": { userId: string; changes: Record<string, unknown> };
  "user.deleted": { userId: string };
  "order.placed": { orderId: string; total: number; items: string[] };
  "order.shipped": { orderId: string; trackingNumber: string };
  "order.cancelled": { orderId: string; reason: string };
}

/** Typed event – payload type is inferred from the name when possible */
type Event<TName extends EventName = EventName> = {
  name: TName;
  timestamp: Date;
  payload: TName extends keyof EventPayloadMap
    ? EventPayloadMap[TName]
    : Record<string, unknown>;
};

// ─── Errors ───────────────────────────────────────────────────────────────────

class EventParseError extends Error {
  constructor(
    message: string,
    public readonly field: string,
    public readonly received: unknown
  ) {
    super(`[EventParseError] ${field}: ${message} (received: ${JSON.stringify(received)})`);
    this.name = "EventParseError";
  }
}

// ─── Guards ───────────────────────────────────────────────────────────────────

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isString(value: unknown): value is string {
  return typeof value === "string";
}

function isNonEmptyString(value: unknown): value is string {
  return isString(value) && value.trim().length > 0;
}

/**
 * Accepts:
 *  - Date instance
 *  - ISO 8601 string  ("2024-01-15T10:30:00.000Z")
 *  - Unix timestamp in ms (number)
 */
function parseTimestamp(value: unknown): Date {
  if (value instanceof Date) {
    if (isNaN(value.getTime())) {
      throw new EventParseError("Invalid Date instance", "timestamp", value);
    }
    return value;
  }

  if (typeof value === "string") {
    const date = new Date(value);
    if (isNaN(date.getTime())) {
      throw new EventParseError("Cannot parse date string", "timestamp", value);
    }
    return date;
  }

  if (typeof value === "number") {
    if (!Number.isFinite(value) || value < 0) {
      throw new EventParseError("Invalid numeric timestamp", "timestamp", value);
    }
    return new Date(value);
  }

  throw new EventParseError(
    "Expected Date, ISO string, or numeric ms timestamp",
    "timestamp",
    value
  );
}

function parsePayload(value: unknown): Record<string, unknown> {
  if (!isPlainObject(value)) {
    throw new EventParseError(
      "Expected a plain object",
      "payload",
      value
    );
  }
  return value;
}

// ─── Main Parser ─────────────────────────────────────────────────────────────

/**
 * Parses an unknown value into a typed `Event`.
 *
 * @throws {EventParseError} when any required field is missing or invalid.
 *
 * @example
 * const event = parseEvent({
 *   name: "user.created",
 *   timestamp: "2024-01-15T10:30:00.000Z",
 *   payload: { userId: "u_123", email: "alice@example.com" },
 * });
 * // event.name    → "user.created"
 * // event.timestamp → Date object
 * // event.payload → { userId: "u_123", email: "alice@example.com" }
 */
function parseEvent(raw: unknown): Event {
  if (!isPlainObject(raw)) {
    throw new EventParseError(
      "Expected a plain object at the top level",
      "root",
      raw
    );
  }

  // ── name ──────────────────────────────────────────────────────────────────
  if (!isNonEmptyString(raw.name)) {
    throw new EventParseError(
      "Expected a non-empty string",
      "name",
      raw.name
    );
  }
  const name: EventName = raw.name;

  // ── timestamp ─────────────────────────────────────────────────────────────
  if (!("timestamp" in raw)) {
    throw new EventParseError("Field is required", "timestamp", undefined);
  }
  const timestamp = parseTimestamp(raw.timestamp);

  // ── payload ───────────────────────────────────────────────────────────────
  if (!("payload" in raw)) {
    throw new EventParseError("Field is required", "payload", undefined);
  }
  const payload = parsePayload(raw.payload);

  return { name, timestamp, payload };
}

// ─── Typed Overload (optional convenience wrapper) ────────────────────────────

/**
 * Narrow the event to a specific known name after parsing.
 *
 * @example
 * const event = parseEventAs("user.created", raw);
 * event.payload.email; // ✅ typed as string
 */
function parseEventAs<TName extends keyof EventPayloadMap>(
  expectedName: TName,
  raw: unknown
): Event<TName> {
  const event = parseEvent(raw);

  if (event.name !== expectedName) {
    throw new EventParseError(
      `Expected name "${expectedName}"`,
      "name",
      event.name
    );
  }

  // We trust the caller's contract here; a full runtime schema check
  // (e.g. with zod) would validate the payload shape too.
  return event as Event<TName>;
}

// ─── Exports ─────────────────────────────────────────────────────────────────

export type { Event, EventName, EventPayloadMap };
export { parseEvent, parseEventAs, EventParseError };
```

