### Key Design Decisions

| Decision | Rationale |
|---|---|
| `Event<TName>` generic | Payload type is **inferred from the name** via `EventPayloadMap` |
| `(string & {})` in `EventName` | Allows arbitrary strings while preserving autocomplete for known names |
| `EventParseError` with `field` | Callers can programmatically inspect *which* field failed |
| `parseTimestamp` accepts 3 formats | Real-world data arrives as strings, numbers, or `Date` objects |
| `parseEventAs` overload | Provides a **narrowed, fully-typed** result without a heavy schema library |

## Event Type Declaration & Parser

```typescript
// ─── Types ────────────────────────────────────────────────────────────────────

/** Supported payload value types (recursive for nested objects/arrays) */
export type PayloadValue =
  | string
  | number
  | boolean
  | null
  | PayloadValue[]
  | { [key: string]: PayloadValue };

/** The canonical Event shape returned by parseEvent */
export interface Event {
  /** Human-readable event identifier, e.g. "user.signed_up" */
  name: string;
  /** Normalised Date object derived from the raw timestamp field */
  timestamp: Date;
  /** Arbitrary structured data attached to the event */
  payload: Record<string, PayloadValue>;
}

// ─── Custom Error ─────────────────────────────────────────────────────────────

export class EventParseError extends Error {
  constructor(
    message: string,
    public readonly field: string,
    public readonly received: unknown
  ) {
    super(`[EventParseError] ${field}: ${message} (received: ${JSON.stringify(received)})`);
    this.name = "EventParseError";
  }
}

// ─── Internal Helpers ─────────────────────────────────────────────────────────

/**
 * Asserts that `value` is a plain, non-null object.
 * Throws if the assertion fails.
 */
function assertPlainObject(
  value: unknown,
  field: string
): asserts value is Record<string, unknown> {
  if (
    value === null ||
    typeof value !== "object" ||
    Array.isArray(value)
  ) {
    throw new EventParseError("must be a plain object", field, value);
  }
}

/**
 * Recursively validates that a value conforms to `PayloadValue`.
 * Throws an `EventParseError` when an unsupported type is encountered.
 */
function validatePayloadValue(value: unknown, path: string): PayloadValue {
  if (value === null) return null;

  switch (typeof value) {
    case "string":
    case "number":
    case "boolean":
      return value;

    case "object": {
      if (Array.isArray(value)) {
        return value.map((item, i) =>
          validatePayloadValue(item, `${path}[${i}]`)
        );
      }

      // Plain object
      const record = value as Record<string, unknown>;
      const result: Record<string, PayloadValue> = {};
      for (const [k, v] of Object.entries(record)) {
        result[k] = validatePayloadValue(v, `${path}.${k}`);
      }
      return result;
    }

    default:
      throw new EventParseError(
        `unsupported payload type "${typeof value}"`,
        path,
        value
      );
  }
}

/**
 * Parses a raw timestamp field into a valid `Date`.
 * Accepts ISO-8601 strings, Unix timestamps (ms or s), or Date instances.
 */
function parseTimestamp(raw: unknown): Date {
  if (raw instanceof Date) {
    if (isNaN(raw.getTime())) {
      throw new EventParseError("invalid Date instance", "timestamp", raw);
    }
    return raw;
  }

  if (typeof raw === "string") {
    const date = new Date(raw);
    if (isNaN(date.getTime())) {
      throw new EventParseError(
        "string is not a valid date/time",
        "timestamp",
        raw
      );
    }
    return date;
  }

  if (typeof raw === "number") {
    // Heuristic: treat values < 1e12 as Unix seconds, otherwise milliseconds
    const ms = raw < 1e12 ? raw * 1000 : raw;
    const date = new Date(ms);
    if (isNaN(date.getTime())) {
      throw new EventParseError(
        "number does not produce a valid date",
        "timestamp",
        raw
      );
    }
    return date;
  }

  throw new EventParseError(
    "must be a string, number, or Date",
    "timestamp",
    raw
  );
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Parses an unknown value into a strongly-typed `Event`.
 *
 * @param raw - Any value (typically parsed JSON from a network request or queue)
 * @returns A validated `Event` object
 * @throws {EventParseError} When any required field is missing or has the wrong type
 *
 * @example
 * const event = parseEvent({
 *   name: "order.placed",
 *   timestamp: "2024-06-01T12:00:00Z",
 *   payload: { orderId: "abc-123", total: 49.99 },
 * });
 */
export function parseEvent(raw: unknown): Event {
  // ── 1. Top-level must be a plain object ───────────────────────────────────
  assertPlainObject(raw, "root");

  // ── 2. Validate `name` ────────────────────────────────────────────────────
  const { name, timestamp: rawTimestamp, payload: rawPayload } = raw;

  if (typeof name !== "string" || name.trim() === "") {
    throw new EventParseError(
      "must be a non-empty string",
      "name",
      name
    );
  }

  // ── 3. Validate `timestamp` ───────────────────────────────────────────────
  const timestamp = parseTimestamp(rawTimestamp);

  // ── 4. Validate `payload` ─────────────────────────────────────────────────
  if (rawPayload === undefined || rawPayload === null) {
    throw new EventParseError(
      "must be present (use an empty object {} if there is no data)",
      "payload",
      rawPayload
    );
  }

  assertPlainObject(rawPayload, "payload");

  const payload: Record<string, PayloadValue> = {};
  for (const [key, value] of Object.entries(rawPayload)) {
    payload[key] = validatePayloadValue(value, `payload.${key}`);
  }

  // ── 5. Return the typed Event ─────────────────────────────────────────────
  return {
    name: name.trim(),
    timestamp,
    payload,
  };
}
```

