## Key Design Decisions

| Decision | Rationale |
|---|---|
| `PayloadValue` recursive type | Allows arbitrary JSON-like nesting without `any` |
| `assertPlainObject` type predicate | Narrows `unknown → Record<string, unknown>` safely |
| Dual timestamp heuristic (`< 1e12`) | Handles both Unix-seconds and Unix-milliseconds inputs |
| `EventParseError` with `field` | Callers can programmatically identify *which* field failed |
| `name.trim()` on output | Normalises accidental whitespace before storage/routing |

## Event Type Declaration & Parser

```typescript
// ─── Domain types ────────────────────────────────────────────────────────────

/** Supported event categories – extend as needed. */
export type EventName =
  | "user.created"
  | "user.updated"
  | "user.deleted"
  | "order.placed"
  | "order.shipped"
  | "order.cancelled"
  | "payment.succeeded"
  | "payment.failed"
  | string; // allow arbitrary names while keeping autocomplete for known ones

/** The canonical, fully-typed event shape used throughout the application. */
export interface Event<
  TName extends EventName = EventName,
  TPayload extends Record<string, unknown> = Record<string, unknown>,
> {
  /** Unique identifier for this event instance. */
  id: string;
  /** Semantic name / topic of the event. */
  name: TName;
  /** When the event occurred (normalised to a JS Date). */
  timestamp: Date;
  /** Arbitrary structured data carried by the event. */
  payload: TPayload;
  /** Optional metadata (source service, correlation id, schema version, …). */
  meta?: EventMeta;
}

export interface EventMeta {
  source?: string;
  correlationId?: string;
  version?: number;
  [key: string]: unknown;
}

// ─── Custom error ─────────────────────────────────────────────────────────────

export class EventParseError extends Error {
  constructor(
    message: string,
    public readonly field: string,
    public readonly received: unknown,
  ) {
    super(`[EventParseError] ${field}: ${message} (got ${JSON.stringify(received)})`);
    this.name = "EventParseError";
  }
}

// ─── Internal helpers ─────────────────────────────────────────────────────────

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function parseId(raw: Record<string, unknown>): string {
  const { id } = raw;

  if (id === undefined || id === null) {
    // Auto-generate when absent so callers aren't forced to supply one.
    return crypto.randomUUID();
  }

  if (typeof id === "string" && id.trim().length > 0) return id.trim();
  if (typeof id === "number") return String(id);

  throw new EventParseError("must be a non-empty string or number", "id", id);
}

function parseName(raw: Record<string, unknown>): EventName {
  const { name } = raw;

  if (typeof name !== "string" || name.trim().length === 0) {
    throw new EventParseError("must be a non-empty string", "name", name);
  }

  return name.trim() as EventName;
}

function parseTimestamp(raw: Record<string, unknown>): Date {
  const { timestamp } = raw;

  // Already a Date
  if (timestamp instanceof Date) {
    if (isNaN(timestamp.getTime())) {
      throw new EventParseError("Date object is invalid", "timestamp", timestamp);
    }
    return timestamp;
  }

  // ISO string or numeric epoch
  if (typeof timestamp === "string" || typeof timestamp === "number") {
    const date = new Date(timestamp);
    if (isNaN(date.getTime())) {
      throw new EventParseError("cannot be parsed into a valid Date", "timestamp", timestamp);
    }
    return date;
  }

  // Fall back to now when absent
  if (timestamp === undefined || timestamp === null) {
    return new Date();
  }

  throw new EventParseError(
    "must be a Date, ISO string, or numeric epoch",
    "timestamp",
    timestamp,
  );
}

function parsePayload(raw: Record<string, unknown>): Record<string, unknown> {
  const { payload } = raw;

  if (payload === undefined || payload === null) return {};

  if (!isRecord(payload)) {
    throw new EventParseError("must be a plain object", "payload", payload);
  }

  return payload;
}

function parseMeta(raw: Record<string, unknown>): EventMeta | undefined {
  const { meta } = raw;

  if (meta === undefined || meta === null) return undefined;

  if (!isRecord(meta)) {
    throw new EventParseError("must be a plain object", "meta", meta);
  }

  const { source, correlationId, version, ...rest } = meta;

  return {
    ...(typeof source === "string" ? { source } : {}),
    ...(typeof correlationId === "string" ? { correlationId } : {}),
    ...(typeof version === "number" ? { version } : {}),
    ...rest,
  };
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Parses an unknown value into a strongly-typed {@link Event}.
 *
 * @throws {EventParseError} when the input cannot be coerced into a valid Event.
 *
 * @example
 * const event = parseEvent({
 *   name: "order.placed",
 *   timestamp: "2024-06-01T12:00:00Z",
 *   payload: { orderId: "abc-123", total: 99.99 },
 * });
 */
export function parseEvent(raw: unknown): Event {
  if (!isRecord(raw)) {
    throw new EventParseError(
      "event must be a plain object",
      "<root>",
      raw,
    );
  }

  return {
    id: parseId(raw),
    name: parseName(raw),
    timestamp: parseTimestamp(raw),
    payload: parsePayload(raw),
    meta: parseMeta(raw),
  };
}

/**
 * Type-safe variant that narrows both the event name and payload type.
 *
 * @example
 * interface OrderPayload { orderId: string; total: number }
 *
 * const event = parseEventAs<"order.placed", OrderPayload>(raw);
 * // event.name    → "order.placed"
 * // event.payload → { orderId: string; total: number }
 */
export function parseEventAs<
  TName extends EventName,
  TPayload extends Record<string, unknown> = Record<string, unknown>,
>(raw: unknown): Event<TName, TPayload> {
  return parseEvent(raw) as Event<TName, TPayload>;
}
```

