### Key Design Decisions

| Decision | Rationale |
|---|---|
| **Separate helper per field** | Each `parseX()` is independently testable and throwable |
| **Graceful defaults** | Missing `id` → auto UUID, missing `timestamp` → `now()`, missing `payload` → `{}` |
| **`EventParseError`** | Carries `field` + `received` for structured logging / monitoring |
| **Generic `parseEventAs`** | Lets callers narrow the type without losing the safety of runtime parsing |
| **`crypto.randomUUID()`** | Built-in, no extra dependency; available in Node ≥ 19 and all modern browsers |

## Event Type Declaration & Parser

```typescript
// ─── Domain types ────────────────────────────────────────────────────────────

/** Allowed payload value types (recursive so nested objects are supported). */
export type PayloadValue =
  | string
  | number
  | boolean
  | null
  | PayloadValue[]
  | { [key: string]: PayloadValue };

/** The canonical Event shape used throughout the application. */
export interface Event {
  /** Human-readable event name, e.g. "user.signed_up" */
  name: string;
  /** When the event occurred (always a valid Date). */
  timestamp: Date;
  /** Arbitrary structured data associated with the event. */
  payload: Record<string, PayloadValue>;
}

// ─── Custom error ─────────────────────────────────────────────────────────────

export class EventParseError extends Error {
  constructor(
    message: string,
    public readonly field: string,
    public readonly received: unknown
  ) {
    super(`[EventParseError] ${field}: ${message} (received: ${JSON.stringify(received)})`);
    this.name = "EventParseError";
  }
}

// ─── Internal helpers ─────────────────────────────────────────────────────────

function assertPlainObject(
  value: unknown,
  field: string
): asserts value is Record<string, unknown> {
  if (
    value === null ||
    typeof value !== "object" ||
    Array.isArray(value)
  ) {
    throw new EventParseError("must be a plain object", field, value);
  }
}

function parseName(raw: unknown): string {
  if (typeof raw !== "string") {
    throw new EventParseError("must be a string", "name", raw);
  }
  const trimmed = raw.trim();
  if (trimmed.length === 0) {
    throw new EventParseError("must not be empty", "name", raw);
  }
  return trimmed;
}

function parseTimestamp(raw: unknown): Date {
  if (raw instanceof Date) {
    if (isNaN(raw.getTime())) {
      throw new EventParseError("invalid Date object", "timestamp", raw);
    }
    return new Date(raw); // defensive copy
  }

  if (typeof raw === "string" || typeof raw === "number") {
    const date = new Date(raw);
    if (isNaN(date.getTime())) {
      throw new EventParseError(
        "cannot be parsed into a valid date",
        "timestamp",
        raw
      );
    }
    return date;
  }

  throw new EventParseError(
    "must be a Date, ISO string, or Unix timestamp (number)",
    "timestamp",
    raw
  );
}

function parsePayloadValue(value: unknown, path: string): PayloadValue {
  if (value === null) return null;

  switch (typeof value) {
    case "string":
    case "number":
    case "boolean":
      return value;

    case "object":
      if (Array.isArray(value)) {
        return value.map((item, i) => parsePayloadValue(item, `${path}[${i}]`));
      }
      // Plain object
      return Object.fromEntries(
        Object.entries(value as Record<string, unknown>).map(([k, v]) => [
          k,
          parsePayloadValue(v, `${path}.${k}`),
        ])
      );

    default:
      throw new EventParseError(
        `unsupported value type "${typeof value}"`,
        path,
        value
      );
  }
}

function parsePayload(raw: unknown): Record<string, PayloadValue> {
  // Treat missing / undefined payload as an empty object
  if (raw === undefined || raw === null) return {};

  assertPlainObject(raw, "payload");

  return Object.fromEntries(
    Object.entries(raw).map(([key, value]) => [
      key,
      parsePayloadValue(value, `payload.${key}`),
    ])
  );
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Parses an unknown value into a strongly-typed {@link Event}.
 *
 * @param raw - Any value (API response, JSON.parse output, etc.)
 * @returns A validated, immutable-friendly Event object.
 * @throws {EventParseError} when validation fails.
 *
 * @example
 * const event = parseEvent({
 *   name: "order.placed",
 *   timestamp: "2024-06-01T12:00:00Z",
 *   payload: { orderId: "abc-123", total: 49.99 },
 * });
 */
export function parseEvent(raw: unknown): Event {
  assertPlainObject(raw, "root");

  return {
    name:      parseName(raw["name"]),
    timestamp: parseTimestamp(raw["timestamp"]),
    payload:   parsePayload(raw["payload"]),
  };
}
```

