### Function Implementation

```typescript
async function fetchRequest(options: RequestOptions): Promise<Response> {
  const { method, url, headers, body } = options;

  if (!url || url.trim() === "") {
    throw new Error("URL is required and cannot be empty.");
  }

  const hasBody = !["GET", "HEAD", "OPTIONS"].includes(method);

  const requestInit: RequestInit = {
    method,
    headers: headers ?? {},
    ...(hasBody && body !== undefined ? { body } : {}),
  };

  try {
    const response = await fetch(url, requestInit);

    if (!response.ok) {
      throw new Error(
        `Request failed: ${response.status} ${response.statusText} [${method} ${url}]`
      );
    }

    return response;
  } catch (error) {
    if (error instanceof Error) {
      throw new Error(`Fetch error: ${error.message}`);
    }
    throw new Error("An unknown error occurred during the fetch request.");
  }
}
```

