  method: "GET" | "POST" | "PUT" | "PATCH" | "DELETE" | "HEAD" | "OPTIONS";
  url: string;
  headers?: Record<string, string>;
  body?: BodyInit | null;
}
```

### Function Implementation

```typescript
async function fetchRequest<T = unknown>(
  options: RequestOptions
): Promise<T> {
  const { method, url, headers, body } = options;

  // Validate URL
  if (!url || url.trim() === "") {
    throw new Error("A valid URL must be provided.");
  }

  // GET and HEAD requests should not have a body
  if ((method === "GET" || method === "HEAD") && body !== undefined && body !== null) {
    throw new Error(`Request method ${method} cannot have a body.`);
  }

  const requestInit: RequestInit = {
    method,
    headers: headers ?? {},
    body: body ?? null,
  };

  const response = await fetch(url, requestInit);

  if (!response.ok) {
    throw new Error(
      `HTTP Error: ${response.status} ${response.statusText} — URL: ${url}`
    );
  }

  // Parse response based on Content-Type
  const contentType = response.headers.get("Content-Type") ?? "";

  if (contentType.includes("application/json")) {
    return response.json() as Promise<T>;
  }

  if (contentType.includes("text/")) {
    return response.text() as Promise<T>;
  }

  return response.blob() as Promise<T>;
}
```

