async function fetchRequest(options: RequestOptions): Promise<Response> {
  const { method, url, headers, body } = options;

  // Validate URL
  try {
    new URL(url);
  } catch {
    throw new Error(`Invalid URL: ${url}`);
  }

  // Build fetch options
  const fetchOptions: RequestInit = {
    method,
    headers: headers ? new Headers(headers) : undefined,
    // Body is not allowed for GET and HEAD requests
    body: method !== "GET" && method !== "HEAD" ? body : undefined,
  };

  const response = await fetch(url, fetchOptions);

  if (!response.ok) {
    throw new Error(
      `Request failed: ${response.status} ${response.statusText} for ${method} ${url}`
    );
  }

  return response;
