### Type Declarations

```typescript
interface RequestOptions {
  method: "GET" | "POST" | "PUT" | "PATCH" | "DELETE" | "HEAD" | "OPTIONS";
  url: string;
  headers?: Record<string, string>;
  body?: BodyInit | Record<string, unknown> | null;
}
```

### Implementation

```typescript
async function fetchRequest<T = unknown>(options: RequestOptions): Promise<T> {
  const { method, url, headers = {}, body } = options;

  // Normalize body: serialize plain objects to JSON
  let normalizedBody: BodyInit | null | undefined;
  const normalizedHeaders: Record<string, string> = { ...headers };

  if (body !== null && body !== undefined) {
    if (
      typeof body === "object" &&
      !(body instanceof FormData) &&
      !(body instanceof URLSearchParams) &&
      !(body instanceof Blob) &&
      !(body instanceof ArrayBuffer) &&
      !(body instanceof ReadableStream)
    ) {
      normalizedBody = JSON.stringify(body);
      normalizedHeaders["Content-Type"] ??= "application/json";
    } else {
      normalizedBody = body as BodyInit;
    }
  }

  const response = await fetch(url, {
    method,
    headers: normalizedHeaders,
    body: ["GET", "HEAD"].includes(method) ? undefined : normalizedBody,
  });

  if (!response.ok) {
    throw new Error(
      `HTTP Error: ${response.status} ${response.statusText} — ${url}`
    );
  }

  // Deserialize response based on Content-Type
  const contentType = response.headers.get("Content-Type") ?? "";

  if (contentType.includes("application/json")) {
    return response.json() as Promise<T>;
  }

  if (contentType.includes("text/")) {
    return response.text() as Promise<T>;
  }

  return response.blob() as Promise<T>;
}
```

