### Function Implementation

```typescript
async function fetchRequest<T = unknown>(
  options: RequestOptions
): Promise<T> {
  const { method, url, headers, body } = options;

  // Validate URL
  if (!url || url.trim() === "") {
    throw new Error("A valid URL must be provided.");
  }

  // Warn if body is provided with a method that typically doesn't use one
  if (body && ["GET", "HEAD"].includes(method)) {
    console.warn(`HTTP method "${method}" should not have a request body.`);
  }

  const requestInit: RequestInit = {
    method,
    headers: {
      "Content-Type": "application/json",
      ...headers,
    },
    body: body ?? null,
  };

  const response = await fetch(url, requestInit);

  if (!response.ok) {
    throw new Error(
      `HTTP Error: ${response.status} ${response.statusText} — URL: ${url}`
    );
  }

  // Handle empty responses (e.g., 204 No Content)
  const contentType = response.headers.get("Content-Type");
  if (!contentType || response.status === 204) {
    return null as T;
  }

  if (contentType.includes("application/json")) {
    return response.json() as Promise<T>;
  }

  return response.text() as unknown as Promise<T>;
}
```

### Usage Examples

```typescript
// --- GET Request ---
interface User {
  id: number;
  name: string;
  email: string;
}

const user = await fetchRequest<User>({
  method: "GET",
  url: "https://jsonplaceholder.typicode.com/users/1",
});

console.log(user.name); // Leanne Graham


// --- POST Request ---
interface Post {
  id: number;
  title: string;
  body: string;
  userId: number;
}

const newPost = await fetchRequest<Post>({
  method: "POST",
  url: "https://jsonplaceholder.typicode.com/posts",
  headers: {
    Authorization: "Bearer my-token",
  },
  body: JSON.stringify({
    title: "Hello World",
    body: "This is a new post.",
    userId: 1,
  }),
});

console.log(newPost.id); // 101


// --- DELETE Request (no content response) ---
await fetchRequest({
  method: "DELETE",
  url: "https://jsonplaceholder.typicode.com/posts/1",
});
```

### Key Design Decisions

| Decision | Reason |
|---|---|
| Generic `<T>` return type | Allows callers to type the response without casting |
| Default `Content-Type: application/json` | Most common use case; can be overridden via `headers` |
| `response.ok` check | Throws on 4xx/5xx instead of silently failing |
| `204 No Content` handling | Prevents attempting to parse an empty body |
| `GET`/`HEAD` body warning | Alerts developers to potentially incorrect usage |

