type HttpMethod =
  | "GET"
  | "POST"
  | "PUT"
  | "PATCH"
  | "DELETE"
  | "HEAD"
  | "OPTIONS";

interface RequestOptions {
  method: HttpMethod;
  url: string;
  headers?: Record<string, string>;
  body?: BodyInit | null;
}

function makeRequest(options: RequestOptions): Promise<Response> {
  const { method, url, headers, body } = options;

  return fetch(url, {
    method,
    headers,
    body,
  });
}
```

