 * Safely parses an unknown input into a typed Event object.
 *
 * @param raw - The raw input data, typically from an API or external source.
 * @returns A validated Event object.
 * @throws {Error} If the input is not a valid event structure.
 */
export function parseEvent(raw: unknown): Event {
  // 1. Check if the input is a non-null object.
  if (typeof raw !== 'object' || raw === null) {
    throw new Error('Input is not a valid object.');
  }

  // We can now safely assume `raw` is an object-like structure.
  // To access its properties, we'll treat it as a record.
  const data = raw as Record<string, unknown>;

  // 2. Validate the 'name' property.
  if (typeof data.name !== 'string' || data.name.trim() === '') {
    throw new Error("Event 'name' property is missing or not a non-empty string.");
  }

  // 3. Validate and parse the 'timestamp' property.
  if (typeof data.timestamp !== 'string' && typeof data.timestamp !== 'number') {
    throw new Error("Event 'timestamp' property is missing or not a string/number.");
  }

  const timestamp = new Date(data.timestamp);
  if (isNaN(timestamp.getTime())) {
    throw new Error("Event 'timestamp' is not a valid date format.");
  }

  // 4. Validate the 'payload' property exists.
  if (!('payload' in data)) {
    throw new Error("Event 'payload' property is missing.");
  }

  // 5. If all checks pass, construct and return the typed Event object.
  return {
    name: data.name,
    timestamp: timestamp,
    payload: data.payload,
  };
}
