 * @param {unknown} raw - The raw data to parse.
 * @returns {Event<T>} The parsed and typed Event object.
 * @throws {Error} If the validation fails.
 */
export function parseEvent<T = unknown>(raw: unknown): Event<T> {
  // 1. Check if the input is a non-null object.
  if (typeof raw !== 'object' || raw === null) {
    throw new Error('Invalid event: Input must be a non-null object.');
  }

  // To safely access properties, we can cast it to a record of unknown values.
  const candidate = raw as Record<string, unknown>;

  // 2. Validate the 'name' property.
  if (typeof candidate.name !== 'string' || candidate.name.trim() === '') {
    throw new Error('Invalid event: "name" property must be a non-empty string.');
  }

  // 3. Validate the 'timestamp' property.
  if (typeof candidate.timestamp !== 'number') {
    throw new Error('Invalid event: "timestamp" property must be a number.');
  }

  // 4. Validate that the 'payload' property exists.
  // We don't validate the type of the payload itself, as that is the
  // responsibility of the code that consumes the event. The generic <T>
  // provides the type assertion for the consumer.
  if (!('payload' in candidate)) {
    throw new Error('Invalid event: "payload" property is missing.');
  }

  // 5. If all checks pass, we can safely cast and return the object.
  // This cast is now justified by our runtime checks.
  return candidate as Event<T>;
}
```

