```typescript
/**
 * A wrapper around the native `fetch` API that simplifies making HTTP requests.
 *
 * @param options - An object containing the request configuration.
 * @returns A Promise that resolves to the `Response` object.
 * @throws An error if the network request fails or if the server returns an error status (4xx, 5xx).
 */
export async function makeRequest(options: RequestOptions): Promise<Response> {
  const { url, method, headers, body } = options;

  // Initialize the headers. Using the Headers constructor is robust.
  const requestHeaders = new Headers(headers);

  // Prepare the RequestInit object for the fetch call.
  const fetchOptions: RequestInit = {
    method,
    headers: requestHeaders,
  };

  // Handle the request body.
  if (body) {
    // If the body is a plain object, stringify it and set the Content-Type header.
    if (typeof body === 'object' && body !== null && !(body instanceof FormData) && !(body instanceof Blob)) {
      fetchOptions.body = JSON.stringify(body);
      // Set content-type to json if it's not already set
      if (!requestHeaders.has('Content-Type')) {
        requestHeaders.set('Content-Type', 'application/json');
      }
    } else {
      // For other types (string, FormData, Blob, etc.), use them as-is.
      fetchOptions.body = body;
    }
  }

  try {
    const response = await fetch(url, fetchOptions);

    // The fetch API does not throw an error for HTTP error statuses (like 404 or 500).
    // We need to check the `response.ok` property and throw an error ourselves.
    if (!response.ok) {
      // Try to get more context from the response body for a better error message.
      const errorData = await response.text();
      throw new Error(`HTTP error! Status: ${response.status}, Body: ${errorData}`);
    }

    return response;
  } catch (error) {
    // This will catch network errors (e.g., no internet) and the error we threw above.
    console.error('Fetch request failed:', error);
    throw error; // Re-throw the error so the caller can handle it.
  }
}
