```typescript
/**
 * A wrapper around the native `fetch` API that simplifies making API requests.
 * It automatically handles JSON stringification, header configuration, and
 * throws an error for non-successful HTTP responses.
 *
 * @param options - The request options (url, method, headers, body).
 * @returns A promise that resolves to the JSON response data.
 * @template T - The expected type of the JSON response data.
 */
export async function apiFetch<T>(options: RequestOptions): Promise<T> {
  const { url, method = 'GET', headers = {}, body } = options;

  // Configure the RequestInit object for the fetch call.
  const config: RequestInit = {
    method,
    headers: {
      // Spread existing headers
      ...headers,
    },
  };

  // If a body is provided, stringify it and set the Content-Type header.
  // This is a common use case for APIs.
  if (body) {
    // We only stringify if the body is a plain object.
    // FormData, Blobs, etc., are passed through as-is.
    if (typeof body === 'object' && body !== null && !(body instanceof FormData) && !(body instanceof Blob)) {
      config.body = JSON.stringify(body);
      // Set default Content-Type for JSON if not already specified.
      if (!config.headers['Content-Type']) {
        config.headers['Content-Type'] = 'application/json';
      }
    } else {
      // For FormData, Blob, string, etc.
      config.body = body;
    }
  }

  try {
    const response = await fetch(url, config);

    // Check if the response was successful (status in the range 200-299).
    if (!response.ok) {
      // Try to get more details from the response body for better error messages.
      const errorData = await response.text();
      throw new Error(
        `HTTP error! Status: ${response.status}. Body: ${errorData}`
      );
    }

    // If the response has no content, we can return an empty object or null.
    // Here we check for the 204 No Content status.
    if (response.status === 204) {
      return null as T;
    }

    // Parse the JSON from the response.
    return response.json() as Promise<T>;

  } catch (error) {
    console.error('Fetch API failed:', error);
    // Re-throw the error to be caught by the caller.
    throw error;
  }
}
