 * A wrapper around the native fetch API that uses a structured RequestOptions object.
 * It automatically stringifies a JSON body and sets the appropriate 'Content-Type' header.
 *
 * @param options - The request options (url, method, headers, body).
 * @returns A Promise that resolves to the Response object.
 */
export function customFetch(options: RequestOptions): Promise<Response> {
  const { url, method, headers, body } = options;

  // The RequestInit object is the second argument to the native fetch function.
  const fetchOptions: RequestInit = {
    method,
    headers,
  };

  // If a body is provided, we need to handle it.
  if (body) {
