This function takes the `RequestOptions` object, constructs the arguments for the native `fetch` call, and returns the resulting `Promise<Response>`.

```typescript
/**
 * A wrapper around the native `fetch` API to simplify making HTTP requests.
 *
 * @param options - The request options object containing url, method, headers, and body.
 * @returns A Promise that resolves to the native Response object.
 */
export function sendRequest(options: RequestOptions): Promise<Response> {
  // Destructure options with default values
  const { url, method = 'GET', headers = {}, body } = options;

  // Create a mutable copy of headers
  const finalHeaders: Record<string, string> = { ...headers };
  let processedBody: any = body;

  // If the body is a plain object and Content-Type is not already set,
  // assume it's JSON. Stringify it and set the correct header.
  if (
    body &&
    typeof body === 'object' &&
    !(body instanceof Blob) &&
    !(body instanceof FormData) &&
    !finalHeaders['Content-Type']
  ) {
    processedBody = JSON.stringify(body);
    finalHeaders['Content-Type'] = 'application/json';
  }

  // Construct the options for the native fetch call
  const fetchOptions: RequestInit = {
    method,
    headers: finalHeaders,
    // Only include the body for methods that support it
    body: (method !== 'GET' && method !== 'HEAD') ? processedBody : undefined,
  };

  // Make the fetch call and return the promise
  return fetch(url, fetchOptions);
}
```

