This function takes the `RequestOptions` object and returns a `fetch` Promise. It includes some helpful logic: if the `body` is a JavaScript object, it automatically stringifies it to JSON and sets the appropriate `Content-Type` header.

```typescript
/**
 * Takes a RequestOptions object and returns a fetch Promise.
 *
 * This function intelligently handles the request body:
 * - If the body is a JavaScript object, it's stringified into JSON.
 * - The 'Content-Type' header is automatically set to 'application/json' for object bodies.
 * - For other body types (like FormData, string, etc.), it's passed through as-is.
 *
 * @param options - The options for the request.
 * @returns A Promise that resolves with the Response object.
 */
export function apiRequest(options: RequestOptions): Promise<Response> {
  const { url, method, headers, body } = options;

  // Start with the user-provided headers, or an empty object.
  const finalHeaders = new Headers(headers);
  let finalBody: BodyInit | undefined;

  // If a body is provided and it's a plain object, stringify it.
  if (body && typeof body === 'object' && !(body instanceof FormData) && !(body instanceof Blob)) {
    finalBody = JSON.stringify(body);
    // Set Content-Type to application/json if it's not already set.
    // This is a common convention for JSON APIs.
    if (!finalHeaders.has('Content-Type')) {
      finalHeaders.set('Content-Type', 'application/json');
    }
  } else {
    // For FormData, Blob, strings, etc., use the body as is.
    finalBody = body;
  }

  // Construct the options for the native fetch call.
  const fetchOptions: globalThis.RequestInit = {
    method,
    headers: finalHeaders,
    body: finalBody,
  };

  return fetch(url, fetchOptions);
}
