### 2. Write the `customFetch` Function

This function takes the `RequestOptions` object, constructs the appropriate arguments for the native `fetch` call, and returns the resulting `Promise<Response>`.

A key feature here is that if a `body` is provided, the function will automatically `JSON.stringify` it and set the `Content-Type` header to `application/json`, which is a very common use case.

```typescript
/**
 * A wrapper around the native fetch API that simplifies making requests.
 * It automatically stringifies the body and sets the 'Content-Type' header for JSON.
 *
 * @param options - The request options (method, url, headers, body).
 * @returns A Promise that resolves to the Response object.
 */
export function customFetch({
  url,
  method = 'GET', // Default to GET
  headers,
  body,
}: RequestOptions): Promise<Response> {
  // The 'RequestInit' object is what the native fetch function expects as its second argument.
  const fetchOptions: RequestInit = {
    method,
    headers,
  };

  // If a body is provided, we'll stringify it and set the appropriate header.
  if (body) {
    // Set the request body.
    fetchOptions.body = JSON.stringify(body);

    // Set the Content-Type header to application/json, but don't overwrite
    // user-provided headers unless they didn't specify a Content-Type.
    fetchOptions.headers = {
      'Content-Type': 'application/json',
      ...headers, // User-defined headers will override the default Content-Type.
    };
  }

  // Make the fetch call and return the promise.
  return fetch(url, fetchOptions);
}
