### 2. The Fetch Wrapper Function

This function takes the `RequestOptions` object, constructs the arguments for the native `fetch` call, and returns the resulting `Promise<Response>`.

```typescript
/**
 * A wrapper around the native fetch API that uses a structured RequestOptions object.
 *
 * @param options - The options for the request, including method, url, headers, and body.
 * @returns A Promise that resolves with the Fetch API's Response object.
 */
export function customFetch(options: RequestOptions): Promise<Response> {
  const { url, method, headers, body } = options;

  // The RequestInit object is the second argument to the native fetch function.
  const config: RequestInit = {
    method,
    headers,
  };

  if (body) {
    // If the body is a JavaScript object, stringify it and set the Content-Type header.
    // This is a common use case for APIs.
    if (typeof body === 'object' && body !== null) {
      config.body = JSON.stringify(body);
      // Prepend the 'Content-Type' header, allowing user-provided headers to override it.
      config.headers = {
        'Content-Type': 'application/json',
        ...headers,
      };
    } else {
      // If the body is already a string, use it directly.
      config.body = body;
    }
  }

  return fetch(url, config);
}
```

