### Enhanced Version with Generics (Recommended)

In a real application, you often want the final JSON data, not just the `Response` object. We can improve our function with generics to handle this, making it more type-safe and easier to use.

This version will automatically parse the JSON and return a typed object.

```typescript
/**
 * An enhanced fetch wrapper that uses generics to return a typed response body.
 * It automatically handles JSON parsing and error checking.
 *
 * @param options - The options for the request.
 * @returns A Promise that resolves with the parsed JSON data of type T.
 */
export async function typedFetch<T>(options: RequestOptions): Promise<T> {
  const { url, method, headers, body } = options;

  const config: RequestInit = {
    method,
    headers,
  };

  if (body) {
    if (typeof body === 'object' && body !== null) {
      config.body = JSON.stringify(body);
      config.headers = {
        'Content-Type': 'application/json',
        ...headers,
      };
    } else {
      config.body = body;
    }
  }

  const response = await fetch(url, config);

  // Check if the request was successful.
  if (!response.ok) {
    // You can enhance error handling here by parsing an error response body
    const errorText = await response.text();
    throw new Error(`HTTP error! Status: ${response.status}, Body: ${errorText}`);
  }

  // Parse the JSON response and cast it to the generic type T.
  return response.json() as Promise<T>;
}

// Example usage of the enhanced function
