  id: number;
  title: string;
  body: string;
  userId: number;
}

async function getSinglePost() {
  try {
    // We specify that we expect the response to conform to the Post interface.
    const post = await typedFetch<Post>({
      method: 'GET',
      url: 'https://jsonplaceholder.typicode.com/posts/1',
    });

    // `post` is now fully typed! No need for `response.json()` or manual casting.
    console.log('Typed Post Title:', post.title); 
  } catch (error) {
    console.error('Failed to fetch post:', error);
  }
}

